function escapeHtml(value=''){const span=document.createElement('span');span.textContent=String(value);return span.innerHTML;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
function setAutosaveState(selector,state,text){const element=document.querySelector(selector);if(!element)return;element.classList.remove('saving','saved','error');element.classList.add(state);element.textContent=text;}
function normalizeContactSearch(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('de-DE').trim();}
function collectContactSearchValues(value,depth=0){if(value===null||value===undefined||depth>3)return[];if(['string','number','boolean'].includes(typeof value))return[String(value)];if(Array.isArray(value))return value.flatMap(item=>collectContactSearchValues(item,depth+1));if(typeof value==='object')return Object.values(value).flatMap(item=>collectContactSearchValues(item,depth+1));return[];}
function customerSearchValues(person){return [...collectContactSearchValues(person.searchSource||person),...(person.isDemo?['DEMO-Kunde Demokunde Testkonto']:[])];}
function demoCustomerBadge(person){return person.isDemo?'<span class="crm-demoBadge">DEMO</span>':'';}
function globalContactRecords(){
  const participantsById=new Map(participants.map(person=>[person.id,person]));
  const linkedLeadsByParticipant=new Map(leads.filter(lead=>lead.converted_user_profile_id).map(lead=>[lead.converted_user_profile_id,lead]));
  const customerRecords=participants.map(person=>{const linkedLead=linkedLeadsByParticipant.get(person.id)||leads.find(lead=>normalizeContactSearch(lead.email)===normalizeContactSearch(person.email));const phone=linkedLead?.phone||person.phone||'';return{key:`customer:${person.id}`,entityType:'participant',id:person.id,name:person.name,email:person.email,phone,customerNumber:person.customerNumber||'',status:person.week?`Woche ${person.week}`:'Onboarding',typeLabel:person.isDemo?'DEMO-Kunde':'Kunde',searchText:normalizeContactSearch([...customerSearchValues(person),...collectContactSearchValues(linkedLead)].join(' '))};});
  const leadRecords=leads.filter(lead=>!lead.converted_user_profile_id||!participantsById.has(lead.converted_user_profile_id)).map(lead=>{const isCustomer=Boolean(lead.converted_user_profile_id);return{key:`${isCustomer?'customer':'lead'}:${lead.id}`,entityType:isCustomer?'participant':'lead',id:isCustomer?lead.converted_user_profile_id:lead.id,name:lead.name||`${lead.first_name||''} ${lead.last_name||''}`.trim()||'Kontakt ohne Namen',email:lead.email||'',phone:lead.mobile_phone||lead.phone||'',customerNumber:lead.customer_number||'',status:leadStatusLabels[lead.status]||lead.status||'Neu',typeLabel:isCustomer?'Kunde':'Interessent',searchText:normalizeContactSearch(collectContactSearchValues(lead).join(' '))};});
  return[...customerRecords,...leadRecords];
}
function globalContactMatches(query){const normalized=normalizeContactSearch(query);if(normalized.length<3)return[];return globalContactRecords().filter(record=>record.searchText.includes(normalized)||normalizeContactSearch(`${record.name} ${record.email} ${record.phone} ${record.customerNumber} ${record.status}`).includes(normalized)).map(record=>{const name=normalizeContactSearch(record.name),email=normalizeContactSearch(record.email),number=normalizeContactSearch(record.customerNumber);const score=name.startsWith(normalized)?0:name.includes(normalized)?1:email.startsWith(normalized)?2:number.startsWith(normalized)?2:3;return{...record,score};}).sort((a,b)=>a.score-b.score||a.name.localeCompare(b.name,'de')).slice(0,8);}
let globalContactSearchSelection=-1;
function closeGlobalContactSearch(){const input=document.querySelector('#globalCrmSearchInput'),results=document.querySelector('#globalCrmSearchResults');if(!input||!results)return;results.hidden=true;results.innerHTML='';input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');globalContactSearchSelection=-1;}
function renderGlobalContactSearch(){const input=document.querySelector('#globalCrmSearchInput'),results=document.querySelector('#globalCrmSearchResults');if(!input||!results)return;const query=input.value.trim();if(normalizeContactSearch(query).length<3)return closeGlobalContactSearch();const matches=globalContactMatches(query);globalContactSearchSelection=Math.min(globalContactSearchSelection,matches.length-1);results.innerHTML=matches.length?matches.map((record,index)=>`<button type="button" role="option" id="global-contact-result-${index}" class="global-contact-result ${index===globalContactSearchSelection?'active':''}" aria-selected="${index===globalContactSearchSelection}" data-global-contact="${escapeHtml(record.key)}"><span class="global-contact-avatar">${escapeHtml(record.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()||'?')}</span><span class="global-contact-copy"><strong>${escapeHtml(record.name)}</strong><small>${escapeHtml([record.email,record.phone].filter(Boolean).join(' · ')||'Keine Kontaktdaten hinterlegt')}</small><i>${escapeHtml([record.customerNumber,record.status].filter(Boolean).join(' · '))}</i></span><em class="global-contact-type ${record.entityType}">${escapeHtml(record.typeLabel)}</em><b aria-hidden="true">→</b></button>`).join(''):`<div class="global-contact-empty"><strong>Keine passende Akte gefunden</strong><span>Prüfe Name, E-Mail, Telefon, Kundennummer oder ein anderes Merkmal.</span></div>`;results.hidden=false;input.setAttribute('aria-expanded','true');if(globalContactSearchSelection>=0)input.setAttribute('aria-activedescendant',`global-contact-result-${globalContactSearchSelection}`);else input.removeAttribute('aria-activedescendant');results.querySelectorAll('[data-global-contact]').forEach(button=>button.addEventListener('click',()=>openGlobalContactResult(globalContactRecords().find(record=>record.key===button.dataset.globalContact))));}
async function openGlobalContactResult(record){if(!record)return;const input=document.querySelector('#globalCrmSearchInput');if(input)input.value='';closeGlobalContactSearch();if(record.entityType==='participant'){showView('participants');await openCustomerDashboard(record.id);}else{showView('leads');await openLeadDashboard(record.id);}}
const globalCrmSearch=document.querySelector('#globalCrmSearch'),globalCrmSearchInput=document.querySelector('#globalCrmSearchInput');
globalCrmSearchInput?.addEventListener('input',()=>{globalContactSearchSelection=-1;renderGlobalContactSearch();});
globalCrmSearchInput?.addEventListener('focus',renderGlobalContactSearch);
globalCrmSearchInput?.addEventListener('keydown',event=>{const matches=globalContactMatches(globalCrmSearchInput.value);if(event.key==='Escape'){closeGlobalContactSearch();globalCrmSearchInput.blur();return;}if(!matches.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const direction=event.key==='ArrowDown'?1:-1;globalContactSearchSelection=globalContactSearchSelection<0?(direction>0?0:matches.length-1):(globalContactSearchSelection+direction+matches.length)%matches.length;renderGlobalContactSearch();}else if(event.key==='Enter'){event.preventDefault();openGlobalContactResult(matches[Math.max(0,globalContactSearchSelection)]);}});
document.addEventListener('click',event=>{if(globalCrmSearch&&!globalCrmSearch.contains(event.target))closeGlobalContactSearch();});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();globalCrmSearchInput?.focus();globalCrmSearchInput?.select();}});
function leadNavigationCounts(){const available=leads.filter(lead=>!lead.converted_user_profile_id&&lead.status!=='customer');return{all:available.length,active:available.filter(lead=>!['lost','later'].includes(lead.status)).length,lost:available.filter(lead=>lead.status==='lost').length,later:available.filter(lead=>lead.status==='later').length};}
function contextItemMarkup(item,index){const[title,description,target,settings,mailbox,communicationSection,customerSection,leadSection]=item;const active=leadSection?activeLeadDashboard&&leadDashboardPage===leadSection:customerSection?(activeCustomerDashboard?customerDashboardPage===customerSection:participantSection===customerSection):index===0;return`<button class="${active?'active':''}" data-context-target="${escapeHtml(target)}" ${settings?`data-context-settings="${escapeHtml(settings)}"`:''} ${mailbox?`data-context-mailbox="${escapeHtml(mailbox)}"`:''} ${communicationSection?`data-context-communication="${escapeHtml(communicationSection)}"`:''} ${customerSection?`data-context-participants="${escapeHtml(customerSection)}"`:''} ${leadSection?`data-context-leads="${escapeHtml(leadSection)}"`:''}><span>${String(index+1).padStart(2,'0')}</span><div><b>${escapeHtml(title)}</b><small>${escapeHtml(description)}</small></div></button>`;}
function customerAge(date){if(!date)return'';const birth=new Date(`${date}T00:00:00`),today=new Date();let age=today.getFullYear()-birth.getFullYear();if(today.getMonth()<birth.getMonth()||today.getMonth()===birth.getMonth()&&today.getDate()<birth.getDate())age-=1;return Number.isFinite(age)&&age>=0?`${age} Jahre`:'';}
function customerContextProfileMarkup(){const person=activeCustomerDashboard?.person,profile=activeCustomerDashboard?.customer?.profile||activeCustomerDashboard?.program?.profile||person||{},photo=profile.photoUrl||'';return`<section class="customer-context-profile"><button type="button" class="customer-context-avatar" data-customer-avatar title="Profilbild ändern">${photo?`<img src="${escapeHtml(photo)}" alt="Profilbild von ${escapeHtml(profile.name||'Kunde')}">`:`<span>${escapeHtml(person?.initials||'KD')}</span>`}<i>+</i></button><strong>${escapeHtml(profile.name||'Kundenakte')}</strong><small>${escapeHtml(profile.customer_number||person?.customerNumber||'Kundennummer wird vergeben')}</small>${profile.birth_date?`<em>♙ ${escapeHtml(new Date(`${profile.birth_date}T00:00:00`).toLocaleDateString('de-DE'))}${customerAge(profile.birth_date)?` (${escapeHtml(customerAge(profile.birth_date))})`:''}</em>`:'<em>Geburtsdatum nicht hinterlegt</em>'}</section>`;}
function customerContextGroupsMarkup(config){let index=0;return`${customerContextProfileMarkup()}${config.detailGroups.map(group=>({...group,items:group.items.filter(item=>canAccessCustomerPage(item[6]))})).filter(group=>group.items.length).map(group=>`<section class="customer-context-group"><p>${escapeHtml(group.label)}</p><nav>${group.items.map(item=>contextItemMarkup(item,index++)).join('')}</nav></section>`).join('')}`;}
function leadContextProfileMarkup(){const lead=activeLeadDashboard?.lead||{},initials=(lead.name||'Interessent').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();return`<section class="customer-context-profile lead-context-profile"><div class="customer-context-avatar"><span>${escapeHtml(initials||'IN')}</span></div><strong>${escapeHtml(lead.name||'Interessentenakte')}</strong><small>Interessent · ${escapeHtml(leadStatusLabels[lead.status]||lead.status||'Neu')}</small><em>${escapeHtml(lead.email||'Keine E-Mail hinterlegt')}</em></section>`;}
function leadContextGroupsMarkup(config){let index=0;return`${leadContextProfileMarkup()}${config.detailGroups.map(group=>`<section class="customer-context-group"><p>${escapeHtml(group.label)}</p><nav>${group.items.map(item=>contextItemMarkup(item,index++)).join('')}</nav></section>`).join('')}`;}
function participantContextGroupsMarkup(config){let index=0;return config.groups.map(group=>({...group,items:group.items.filter(item=>canAccessCustomerPage(item[6]))})).filter(group=>group.items.length).map(group=>`<section class="customer-context-group"><p>${escapeHtml(group.label)}</p><nav>${group.items.map(item=>contextItemMarkup(item,index++)).join('')}</nav></section>`).join('');}
function renderLeadListContextNavigation(nav,config){const counts=leadNavigationCounts();nav.innerHTML=config.groups.map((group,groupIndex)=>`<section class="lead-context-group"><button type="button" class="lead-context-group-toggle" data-lead-context-group="${groupIndex}" aria-expanded="true"><span>${escapeHtml(group.label)}</span><i>⌄</i></button><div class="lead-context-group-items">${group.items.map(([title,description,filter])=>`<button type="button" class="lead-context-filter ${leadListFilter===filter?'active':''}" data-lead-filter="${escapeHtml(filter)}"><div><b>${escapeHtml(title)}</b><small>${escapeHtml(description)}</small></div>${filter==='all'?'':`<span>${counts[filter]||0}</span>`}</button>`).join('')}</div></section>`).join('');nav.querySelectorAll('[data-lead-context-group]').forEach(button=>button.addEventListener('click',()=>{const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));button.closest('.lead-context-group').classList.toggle('collapsed',expanded);}));nav.querySelectorAll('[data-lead-filter]').forEach(button=>button.addEventListener('click',()=>setLeadListFilter(button.dataset.leadFilter)));}
function renderContextNavigation(name){const config=contextNavigation[name]||contextNavigation.command;document.querySelector('#contextIcon').textContent=config.icon;document.querySelector('#contextTitle').textContent=titles[name]||titles.command;const nav=document.querySelector('#contextNav');if(name==='leads'&&!activeLeadDashboard)return renderLeadListContextNavigation(nav,config);if(name==='leads'&&activeLeadDashboard)nav.innerHTML=leadContextGroupsMarkup(config);else if(name==='participants'&&activeCustomerDashboard)nav.innerHTML=customerContextGroupsMarkup(config);else if(name==='participants'&&config.groups)nav.innerHTML=participantContextGroupsMarkup(config);else{const configuredItems=config.items,items=name==='participants'?configuredItems.filter(item=>canAccessCustomerPage(item[6])):name==='settings'?configuredItems.filter(item=>item[3]!=='users'||activeStaffPermissions.includes('users')):configuredItems;nav.innerHTML=`<p>${escapeHtml(config.label)}</p><nav>${items.map(contextItemMarkup).join('')}</nav>`;}nav.querySelectorAll('[data-context-target]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.contextParticipants==='conversation'&&activeCustomerDashboard){const leadId=activeCustomerDashboard.leadDashboard?.lead?.id||activeCustomerDashboard.person?.linkedLeadId;if(leadId)openLeadEditor(leadId);else toast('Für diesen Kunden ist noch kein Verkaufsgespräch verknüpft.');return;}nav.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));if(button.dataset.contextLeads&&activeLeadDashboard){const page=button.dataset.contextLeads;setLeadDashboardPage(page,false);if(page==='conversation')openLeadEditor(activeLeadDashboard.lead.id);return;}if(button.dataset.contextParticipants){if(activeCustomerDashboard)setCustomerDashboardPage(button.dataset.contextParticipants,false);else setParticipantSection(button.dataset.contextParticipants,false);}if(button.dataset.contextSettings)showSettingsPanel(button.dataset.contextSettings);if(button.dataset.contextCommunication&&typeof setCommunicationSection==='function')setCommunicationSection(button.dataset.contextCommunication,button.dataset.contextMailbox);else if(button.dataset.contextMailbox)setCommunicationFolder(button.dataset.contextMailbox);const activeView=document.querySelector('.view.active');const target=activeView?.matches(button.dataset.contextTarget)?activeView:activeView?.querySelector(button.dataset.contextTarget);target?.scrollIntoView({behavior:'smooth',block:'start'});}));nav.querySelector('[data-customer-avatar]')?.addEventListener('click',()=>document.querySelector('#customerAvatarInput')?.click());}
function showView(name){const isDashboard=name==='command',contextNav=document.querySelector('.context-nav');if(name==='participants')resetCustomerListView();document.body.classList.toggle('dashboard-view',isDashboard);contextNav.hidden=isDashboard;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.panel===name));document.querySelectorAll('.sidebar nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.querySelector('#viewTitle').textContent=titles[name];if(name==='settings')showSettingsPanel('general');if(!isDashboard)renderContextNavigation(name);if(isDashboard)loadCommandDashboard();if(name==='gates')loadGateSettings();if(name==='communications'){loadCommunications();if(typeof loadCommunicationCenter==='function')loadCommunicationCenter();}window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.view==='leads')resetLeadListView();showView(button.dataset.view);}));
document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.jump)));
function showSettingsPanel(name){document.querySelectorAll('[data-settings-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.settingsPanel===name));document.querySelectorAll('[data-settings-tab]').forEach(button=>button.classList.toggle('active',button.dataset.settingsTab===name));if(name==='tariffs')loadServiceTariffs().catch(error=>toast(error.message));if(name==='appointments')loadBookingSettings().catch(error=>toast(error.message));if(name==='questions')loadClarityQuestions();if(name==='integrations')loadSystemStatus();if(name==='signatures'&&typeof loadCommunicationCenter==='function')loadCommunicationCenter();if(name==='users'&&activeStaffPermissions.includes('users'))loadUsers();}
document.querySelectorAll('[data-settings-tab]').forEach(button=>button.addEventListener('click',()=>showSettingsPanel(button.dataset.settingsTab)));
document.querySelectorAll('[data-settings-jump]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.settingsJump)));

let clarityQuestions=[];
let clarityQuestionsLoaded=false;
const clarityTypeLabels={dialog:'Dialogfrage',scale:'Skala',upload:'Upload-Hinweis',confirmation:'Bestätigung',external:'Technischer Schritt',structured:'Strukturierter Schritt'};
function renderClarityQuestions(){const list=document.querySelector('#clarityQuestionList');if(!list)return;const week=document.querySelector('#clarityQuestionWeek')?.value||'';const query=(document.querySelector('#clarityQuestionSearch')?.value||'').trim().toLowerCase();const filtered=clarityQuestions.filter(item=>(!week||String(item.week)===week)&&(!query||`${item.title} ${item.prompt_text} ${item.guidance_text||''} ${item.completion_criteria||''}`.toLowerCase().includes(query)));document.querySelector('#clarityQuestionCount').textContent=`${filtered.length} von ${clarityQuestions.length} Fragen`;list.innerHTML=filtered.length?filtered.map(item=>`<form class="clarity-question-card" data-question-key="${escapeHtml(item.question_key)}"><div class="question-card-head"><div><span>Woche ${Number(item.week)} · Schritt ${Number(item.sort_order)}</span><h4>${escapeHtml(item.title)}</h4></div><i>${escapeHtml(clarityTypeLabels[item.prompt_type]||item.prompt_type)}</i></div><div class="question-builder-grid"><label>Frage an den Kunden<textarea name="promptText" rows="3" minlength="5" maxlength="2000" required>${escapeHtml(item.prompt_text)}</textarea><small>Diese Formulierung schreibt Clara in den aktuellen Chat.</small></label><label>Details für Clara<textarea name="guidanceText" rows="3" minlength="5" maxlength="4000" required>${escapeHtml(item.guidance_text||'')}</textarea><small>Interne Leitplanken für Rückfragen, Ton und Fokus.</small></label><label class="completion-criteria">Wann ist die Frage vollständig geklärt?<textarea name="completionCriteria" rows="3" minlength="5" maxlength="4000" required>${escapeHtml(item.completion_criteria||'')}</textarea><small>Nur wenn diese Kriterien erfüllt sind und keine Rückfrage offen ist, darf Clara weitergehen.</small></label></div><div class="question-card-actions"><small>${item.prompt_text===item.default_prompt_text&&item.guidance_text===item.default_guidance_text&&item.completion_criteria===item.default_completion_criteria?'Standard-Baustein':'Individuell angepasst'}${item.updated_at?` · ${new Date(item.updated_at).toLocaleString('de-DE')}`:''}</small><div><button class="secondary" type="button" data-reset-question>Standard wiederherstellen</button><button class="primary" type="submit">Baustein speichern</button></div></div></form>`).join(''):'<div class="empty">Keine Fragen für diesen Filter gefunden.</div>';}
async function loadClarityQuestions(force=false){if(clarityQuestionsLoaded&&!force){renderClarityQuestions();return;}const list=document.querySelector('#clarityQuestionList');if(list)list.innerHTML='<div class="empty">Klarheitsfragen werden geladen …</div>';try{const response=await fetch('/api/clarity?action=settings');const data=await response.json();if(!response.ok)throw new Error(data.error);clarityQuestions=data.questions||[];clarityQuestionsLoaded=true;renderClarityQuestions();}catch(error){if(list)list.innerHTML=`<div class="empty">${escapeHtml(error.message||'Klarheitsfragen konnten nicht geladen werden.')}</div>`;}}
async function updateClarityQuestion(form,action='save'){const questionKey=form.dataset.questionKey;const button=form.querySelector(action==='reset'?'[data-reset-question]':'button[type="submit"]');const promptText=form.elements.promptText.value.trim();const guidanceText=form.elements.guidanceText.value.trim();const completionCriteria=form.elements.completionCriteria.value.trim();button.disabled=true;try{const response=await fetch('/api/clarity?action=settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({questionKey,promptText,guidanceText,completionCriteria,action})});const data=await response.json();if(!response.ok)throw new Error(data.error);const index=clarityQuestions.findIndex(item=>item.question_key===questionKey);if(index>=0)clarityQuestions[index]={...clarityQuestions[index],...data.question};renderClarityQuestions();toast(action==='reset'?'Standard-Baustein wurde wiederhergestellt.':'Frage, Clara-Details und Abschlusskriterien wurden gespeichert.');}catch(error){toast(error.message||'Prozess-Baustein konnte nicht gespeichert werden.');button.disabled=false;}}
document.querySelector('#clarityQuestionWeek')?.addEventListener('change',renderClarityQuestions);
document.querySelector('#clarityQuestionSearch')?.addEventListener('input',renderClarityQuestions);
document.querySelector('#clarityQuestionList')?.addEventListener('submit',event=>{const form=event.target.closest('[data-question-key]');if(!form)return;event.preventDefault();updateClarityQuestion(form);});
document.querySelector('#clarityQuestionList')?.addEventListener('click',event=>{const button=event.target.closest('[data-reset-question]');if(!button)return;const form=button.closest('[data-question-key]');if(confirm('Diese Frage wirklich auf den ausgelieferten Standard zurücksetzen?'))updateClarityQuestion(form,'reset');});

function accessModeLabel(){return 'Automatisch nach Zeitplan';}
function participantMarkup(person, table=false){const info=`<div class="participant"><span class="avatar">${escapeHtml(person.initials)}</span><div><strong>${escapeHtml(person.name)}${demoCustomerBadge(person)}</strong><small>${escapeHtml(person.email)}</small></div></div>`,phase=customerPhase(person);if(table)return `<div class="table-data participant-control-row" data-participant-id="${escapeHtml(person.id)}">${info}<span class="phase"><b>${escapeHtml(phase)}</b>${escapeHtml(customerStatusLabel(person))}</span><div><div class="progress"><i style="width:${person.progress}%"></i></div><div class="progress-label">${person.progress}% · ${person.completedWeeks.length} von 8 Wochen</div></div><strong>${person.startDate?new Date(`${person.startDate}T00:00:00`).toLocaleDateString('de-DE'):'—'}</strong><span class="gate"><button class="program-open" data-program-id="${escapeHtml(person.id)}">Kundenakte öffnen →</button></span></div>`;return `<div class="participant-row">${info}<span class="phase"><b>${escapeHtml(phase)}</b>${escapeHtml(customerStatusLabel(person))}</span><div><div class="progress"><i style="width:${person.progress}%"></i></div><div class="progress-label">${person.progress}%</div></div><span class="gate"><b>${escapeHtml(person.next)}</b>${escapeHtml(person.programStatus||'aktiv')}</span></div>`;}
function customerPhase(person){return Number(person.processWeek||person.week)>0?`Woche ${Number(person.processWeek||person.week)}`:'Onboarding';}
function customerStatus(person){if(person.progress>=100)return'completed';return person.programStatus==='paused'?'paused':'active';}
function customerStatusLabel(person){return{active:'Aktiv',paused:'Pausiert',completed:'Programm abgeschlossen'}[customerStatus(person)];}
function customerAddress(person){return [person.street,[person.postalCode,person.city].filter(Boolean).join(' '),person.country].filter(Boolean).join(' · ')||'Anschrift noch nicht hinterlegt';}
function customerOverviewMarkup(person){
  const phase=customerPhase(person),start=person.startDate?new Date(`${person.startDate}T00:00:00`).toLocaleDateString('de-DE'):'Noch nicht festgelegt';
  if(participantViewMode==='list')return participantMarkup(person,true);
  if(participantViewMode==='details')return `<article class="customer-detail-card" data-participant-id="${escapeHtml(person.id)}"><div class="customer-detail-profile"><span class="customer-card-avatar">${escapeHtml(person.initials)}</span><div><small>${escapeHtml(person.customerNumber||'Kundennummer wird vergeben')}</small><h2>${escapeHtml(person.name)}${demoCustomerBadge(person)}</h2><p>${escapeHtml(person.email)}${person.phone?` · ${escapeHtml(person.phone)}`:''}</p></div><button class="program-open" data-program-id="${escapeHtml(person.id)}">Kundenakte öffnen →</button></div><div class="customer-detail-data"><div><small>Status</small><strong>${escapeHtml(phase)}</strong><span>${escapeHtml(person.programStatus||'aktiv')}</span></div><div><small>Programmstart</small><strong>${escapeHtml(start)}</strong><span>${person.progress}% abgeschlossen</span></div><div><small>Name & Adresse</small><strong>${escapeHtml(customerAddress(person))}</strong><span>${escapeHtml(person.birthDate?`Geboren am ${new Date(`${person.birthDate}T00:00:00`).toLocaleDateString('de-DE')}`:'Geburtsdatum nicht hinterlegt')}</span></div></div><div class="customer-card-progress"><i style="width:${person.progress}%"></i></div></article>`;
  return `<article class="customer-tile-card" data-participant-id="${escapeHtml(person.id)}"><div class="customer-tile-top"><span class="customer-card-avatar">${escapeHtml(person.initials)}</span><i>${escapeHtml(phase)}</i></div><small>${escapeHtml(person.customerNumber||'Kundennummer wird vergeben')}</small><h2>${escapeHtml(person.name)}${demoCustomerBadge(person)}</h2><p>${escapeHtml(person.email)}</p><div class="customer-card-progress"><i style="width:${person.progress}%"></i></div><div class="customer-tile-meta"><span>${person.progress}% Fortschritt</span><span>Start ${escapeHtml(start)}</span></div><button class="program-open" data-program-id="${escapeHtml(person.id)}">Kundenakte öffnen →</button></article>`;
}
function dashboardParticipantMarkup(person){const status=customerStatus(person),phase=customerPhase(person);return `<button type="button" class="dashboard-customer-case" data-dashboard-participant-id="${escapeHtml(person.id)}"><span class="avatar">${escapeHtml(person.initials)}</span><span class="dashboard-case-person"><strong>${escapeHtml(person.name)}${demoCustomerBadge(person)}</strong><small>${escapeHtml(person.customerNumber||person.email)}</small></span><span class="dashboard-case-stage"><b>${escapeHtml(phase)}</b><small>${escapeHtml(person.completedWeeks.length)} von 8 Wochen abgeschlossen</small></span><span class="dashboard-case-progress"><i><b style="width:${person.progress}%"></b></i><small>${person.progress} %</small></span><em class="dashboard-case-status ${status}">${escapeHtml(customerStatusLabel(person))}</em><span class="dashboard-case-open">Prozess ansehen →</span></button>`;}
function renderParticipants(){const query=normalizeContactSearch(document.querySelector('#participantSearch')?.value||''),week=document.querySelector('#weekFilter')?.value||'',status=document.querySelector('#participantStatusFilter')?.value||'',sort=document.querySelector('#participantSort')?.value||'newest';const filtered=participants.filter(person=>(!query||normalizeContactSearch(customerSearchValues(person).join(' ')).includes(query))&&(!week||String(person.processWeek)===week)&&(!status||customerStatus(person)===status)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'de'):sort==='process'?a.processWeek-b.processWeek||a.name.localeCompare(b.name,'de'):sort==='progress'?b.progress-a.progress||a.name.localeCompare(b.name,'de'):new Date(b.customerSince||0)-new Date(a.customerSince||0));const running=participants.filter(person=>customerStatus(person)!=='completed').sort((a,b)=>Number(a.processWeek)-Number(b.processWeek)||a.name.localeCompare(b.name,'de'));const dashboard=document.querySelector('#dashboardParticipants');dashboard.innerHTML=running.length?running.map(dashboardParticipantMarkup).join(''):'<div class="empty">Aktuell gibt es keine laufenden Kundenfälle.</div>';const runningCount=document.querySelector('#dashboardRunningCount');if(runningCount)runningCount.textContent=`${running.length} ${running.length===1?'Fall':'Fälle'}`;dashboard.querySelectorAll('[data-dashboard-participant-id]').forEach(button=>button.addEventListener('click',async()=>{showView('participants');await openCustomerDashboard(button.dataset.dashboardParticipantId,'program');}));const rows=document.querySelector('#participantRows');rows.className=`customer-overview-results ${participantViewMode}`;const listHead=participantViewMode==='list'?'<div class="customer-list-head"><span>Kunde</span><span>Prozessschritt</span><span>Fortschritt</span><span>Startdatum</span><span>Kundenakte</span></div>':'';rows.innerHTML=filtered.length?`${listHead}<div class="customer-result-body">${filtered.map(customerOverviewMarkup).join('')}</div>`:'<div class="empty">Keine Kunden für diese Suche oder Filterauswahl gefunden.</div>';document.querySelector('#participantResultCount').textContent=`${filtered.length} von ${participants.length} ${participants.length===1?'Kunde':'Kunden'}`;document.querySelectorAll('[data-participant-view]').forEach(button=>button.classList.toggle('active',button.dataset.participantView===participantViewMode));rows.querySelectorAll('[data-program-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openCustomerDashboard(button.dataset.programId);}));rows.querySelectorAll('[data-participant-id]').forEach(row=>row.addEventListener('click',()=>openCustomerDashboard(row.dataset.participantId)));}
function setParticipantViewMode(mode){if(!['tiles','list','details'].includes(mode))return;participantViewMode=mode;renderParticipants();}
function setParticipantSection(section,syncNavigation=true){participantSection=section==='logins'?'logins':'overview';const overview=document.querySelector('#participantOverview'),logins=document.querySelector('#participantLoginManager'),dashboard=document.querySelector('#customerDashboard');if(overview)overview.hidden=participantSection!=='overview';if(logins)logins.hidden=participantSection!=='logins';if(dashboard)dashboard.hidden=true;if(syncNavigation&&document.querySelector('[data-panel="participants"]')?.classList.contains('active'))renderContextNavigation('participants');}
function resetCustomerListView(){activeCustomerDashboard=null;customerDashboardPage='dashboard';setParticipantSection('overview',false);}
const customerConversationLabels=['Sind Name, E-Mail-Adresse und Telefonnummer korrekt?','Wie sieht die berufliche Situation momentan aus?','Was möchte der Kunde durch das Coaching konkret erreichen?','Was hindert den Kunden momentan am stärksten daran?','Was wurde bisher versucht und warum hat es noch nicht funktioniert?','Wie verbindlich ist die Bereitschaft für die nächsten Schritte?'];
function customerProcessWeek(program){const configured=Number(program?.access?.processWeek);if(Number.isInteger(configured)&&configured>=0&&configured<=8)return configured;const completed=new Set((program?.access?.completedWeeks||[]).map(Number));return Array.from({length:8},(_,index)=>index+1).find(week=>!completed.has(week))||8;}
function customerWeekMarkup(program){const states=program?.access?.weekStates||[],processWeek=customerProcessWeek(program);return Array.from({length:8},(_,index)=>{const week=index+1,state=states.find(item=>Number(item.week)===week)||{},definition=gateData.find(item=>Number(item.week)===week),current=processWeek===week;return`<article class="customer-week-item ${state.completed?'completed':current?'current':state.accessible?'available':'scheduled'}"><span>${state.completed?'✓':week}</span><small>Woche ${week}</small><strong>${escapeHtml(definition?.title||`Woche ${week}`)}</strong><i>${state.completed?'Abgeschlossen':current?'Aktueller Prozessschritt':state.accessible?'Verfügbar':'Geplant'}</i></article>`;}).join('');}
function customerProcessStateLabel(item,currentWeek){if(item.completed)return['Abgeschlossen','completed'];if(Number(item.week)===currentWeek)return[item.reason==='participant_paused'?'Aktuelle Woche · pausiert':'Aktuelle Woche','current'];if(item.accessible)return['Freigegeben','available'];return[item.unlocksAt?`Gesperrt bis ${new Date(`${item.unlocksAt}T00:00:00`).toLocaleDateString('de-DE')}`:'Noch gesperrt','locked'];}
function customerProcessAnswerMarkup(answer){return `<article class="customer-process-answer"><div><span>${answer.status==='completed'?'✓':'•'}</span><strong>${escapeHtml(answer.label)}</strong></div>${answer.question?`<small>${escapeHtml(answer.question)}</small>`:''}<p>${escapeHtml(answer.value)}</p></article>`;}
function customerProcessGates(program,week){const released=Number(program?.access?.processWeek)>0&&(program?.access?.automaticUnlockedWeeks||[]).includes(Number(week));return(program?.gates||[]).filter(gate=>Number(gate.week)===Number(week)).map(gate=>released?gate:{...gate,completed_at:null});}
function renderCustomerProcess(data){const program=data.program||{},currentWeek=customerProcessWeek(program),weeks=program.processWeeks||[],selectedWeek=weeks.some(item=>Number(item.week)===Number(customerProcessSelectedWeek))?Number(customerProcessSelectedWeek):(currentWeek||1),item=weeks.find(entry=>Number(entry.week)===selectedWeek)||{week:selectedWeek,title:gateData.find(entry=>Number(entry.week)===selectedWeek)?.title||`Woche ${selectedWeek}`,answers:[]},[stateLabel,stateClass]=customerProcessStateLabel(item,currentWeek),definition=gateData.find(entry=>Number(entry.week)===selectedWeek),gates=customerProcessGates(program,selectedWeek);customerProcessSelectedWeek=selectedWeek;const overall=document.querySelector('#customerProcessOverallState');if(overall){overall.textContent=currentWeek?`Woche ${currentWeek} von 8${program.access?.status==='paused'?' · pausiert':''}`:'Onboarding läuft';overall.className=`customer-page-state ${currentWeek?'active':''}`;}const nav=document.querySelector('#customerProcessWeekNav');if(nav)nav.innerHTML=weeks.map(week=>{const[label,tone]=customerProcessStateLabel(week,currentWeek);return`<button type="button" class="${Number(week.week)===selectedWeek?'active':''} ${tone}" data-customer-process-week="${week.week}"><span>${week.completed?'✓':week.week}</span><div><small>Woche ${week.week}</small><strong>${escapeHtml(week.title)}</strong><i>${escapeHtml(label)}</i></div></button>`;}).join('');const detail=document.querySelector('#customerProcessDetail');if(!detail)return;const releaseCopy=item.unlocksAt?new Date(`${item.unlocksAt}T00:00:00`).toLocaleDateString('de-DE'):'Noch nicht terminiert',updated=item.updatedAt?new Date(item.updatedAt).toLocaleString('de-DE'):'Noch keine Eingabe';detail.innerHTML=`<header><div><p class="eyebrow">Woche ${selectedWeek} · ${escapeHtml(definition?.title||item.title)}</p><h2>${escapeHtml(item.currentStep||'Wochenübersicht')}</h2><p>${escapeHtml(definition?.description||'Alle Eingaben und Pflichtschritte dieser Prozesswoche.')}</p></div><span class="customer-process-badge ${stateClass}">${escapeHtml(stateLabel)}</span></header><div class="customer-process-facts"><div><small>Freischaltung</small><strong>${escapeHtml(releaseCopy)}</strong></div><div><small>Letzte Kundeneingabe</small><strong>${escapeHtml(updated)}</strong></div><div><small>Pflichtschritte</small><strong>${gates.filter(gate=>gate.completed_at).length} von ${gates.length} erfüllt</strong></div></div><section class="customer-process-section"><div class="customer-process-section-head"><div><small>Kundeneingaben</small><h3>Was der Kunde eingegeben hat</h3></div><span>${item.answers?.length||0} Einträge</span></div>${item.answers?.length?`<div class="customer-process-answers">${item.answers.map(customerProcessAnswerMarkup).join('')}</div>`:`<div class="customer-process-empty"><strong>Noch keine Eingaben in Woche ${selectedWeek}</strong><p>${stateClass==='locked'?'Diese Woche ist zeitlich gesperrt. Eingaben sind erst ab der Freischaltung möglich.':'Sobald der Kunde diese Woche bearbeitet, erscheinen seine Antworten hier automatisch.'}</p></div>`}</section><section class="customer-process-section"><div class="customer-process-section-head"><div><small>Wochen-Gates</small><h3>Pflichtschritte und Abschlussstatus</h3></div></div><div class="customer-process-gates">${gates.length?gates.map(gate=>`<div class="${gate.completed_at?'completed':''}"><span>${gate.completed_at?'✓':'○'}</span><strong>${escapeHtml(gate.label)}</strong><small>${gate.completed_at?`Erfüllt am ${new Date(gate.completed_at).toLocaleDateString('de-DE')}`:'Noch offen'}</small></div>`).join(''):'<div class="customer-process-empty"><p>Für diese Woche sind keine Gates hinterlegt.</p></div>'}</div></section>`;}
function customerContactMarkup(profile,{compact=false,editable=false}={}){
  const mobile=profile.mobile_phone||'',whatsapp=profile.whatsapp_phone||(profile.whatsapp_same_as_mobile?mobile:''),addressParts=[profile.street,[profile.postal_code,profile.city].filter(Boolean).join(' '),profile.country].filter(Boolean),address=addressParts.map(escapeHtml).join('<br>')||'Noch nicht hinterlegt';
  const fields=[
    {key:'name',label:'Name',value:escapeHtml(profile.name||'Nicht hinterlegt')},
    {key:'birthDate',label:'Geburtsdatum',value:profile.birth_date?new Date(`${profile.birth_date}T00:00:00`).toLocaleDateString('de-DE'):'Nicht hinterlegt'},
    {key:'street',label:'Anschrift',value:address,wide:true},
    {key:'email',label:'E-Mail',value:escapeHtml(profile.email||'Nicht hinterlegt')},
    {key:'phone',label:'Telefon',value:escapeHtml(profile.phone||'Nicht hinterlegt')},
    {key:'mobilePhone',label:'Mobilnummer',value:escapeHtml(mobile||'Nicht hinterlegt')},
    {key:'whatsappPhone',label:'WhatsApp',value:`${escapeHtml(whatsapp||'Nicht hinterlegt')}<small>${profile.whatsapp_same_as_mobile?'Identisch mit Mobilnummer':'Eigene WhatsApp-Nummer'}</small>`},
  ];
  const visible=compact?fields.filter(field=>['name','street','email','mobilePhone'].includes(field.key)):fields;
  return`<dl class="customer-contact-data ${compact?'compact':''}">${visible.map(field=>`<div class="${field.wide?'wide':''} ${editable?'editable':''}"><dt>${escapeHtml(field.label)}</dt><dd>${field.value}</dd>${editable&&!field.protected?`<button type="button" class="customer-contact-edit" data-edit-customer-field="${field.key}" aria-label="${escapeHtml(field.label)} bearbeiten"><span>Ändern</span><b aria-hidden="true">↗</b></button>`:field.protected?'<span class="customer-contact-protected">Portalzugang</span>':''}</div>`).join('')}</dl>`;
}
function renderCustomerConversation(data){const lead=data.leadDashboard?.lead,form=document.querySelector('#customerConversationForm'),container=document.querySelector('#customerConversationQuestions');if(!lead){container.innerHTML='<div class="empty">Zu diesem Kunden wurde keine frühere Interessentenakte gefunden.</div>';form.querySelector('[type="submit"]').disabled=true;return;}form.querySelector('[type="submit"]').disabled=false;const answers=lead.qualification_answers||{};container.innerHTML=customerConversationLabels.map((label,index)=>`<label><b>${index+1}. ${escapeHtml(label)}</b><textarea name="q${index+1}" rows="3">${escapeHtml(answers[`q${index+1}`]||'')}</textarea></label>`).join('');form.elements.internalNotes.value=lead.internal_notes||'';customerConversationRevision=0;customerConversationPersistedRevision=0;setAutosaveState('#customerConversationAutosaveStatus','saved','Alle Änderungen gespeichert');const completed=['consultation','offer','customer'].includes(lead.status);document.querySelector('#customerConversationState').textContent=completed?'Gespräch dokumentiert':'Dokumentation offen';document.querySelector('#customerConversationAppointment').innerHTML=lead.appointment_start?`<strong>Termin: ${crmDate(lead.appointment_start)}</strong>${lead.meet_url?`<a href="${escapeHtml(lead.meet_url)}" target="_blank" rel="noopener">Google Meet öffnen ↗</a>`:''}`:'<span>Noch kein Gesprächstermin hinterlegt</span>';}
function customerDocumentPreviewAttributes({url,title,fileName,mimeType}){return` data-customer-document-preview data-document-url="${escapeHtml(url)}" data-document-title="${escapeHtml(title||fileName||'Dokument ansehen')}" data-document-file="${escapeHtml(fileName||'Originaldatei')}" data-document-mime="${escapeHtml(mimeType||'application/octet-stream')}" tabindex="0" role="button" aria-haspopup="dialog"`;}
function customerDocumentMarkup(document,person){const size=document.byte_size?`${Math.max(1,Math.round(Number(document.byte_size)/1024))} KB`:'',source=document.source==='staff'?'Vom Team bereitgestellt':document.source==='system'?'Vom System erstellt':'Vom Kunden hochgeladen',title=document.display_title||document.original_file_name,url=`/api/customer-records?action=document-download&participantId=${encodeURIComponent(person.id)}&documentId=${encodeURIComponent(document.id)}`;return`<article class="is-previewable"${customerDocumentPreviewAttributes({url,title,fileName:document.original_file_name,mimeType:document.mime_type})}><span>▤</span><div><strong>${escapeHtml(title)}</strong><small>${escapeHtml([source,`Woche ${document.week||0}`,size,crmDate(document.created_at)].filter(Boolean).join(' · '))}</small><i>${escapeHtml(document.original_file_name)}</i></div><button type="button">Ansehen ↗</button></article>`;}
function renderCustomerDocuments(data){const {customer,person}=data,contracts=customer?.contracts||[],documents=customer?.documents||[],leadId=customer?.lead?.id||person.linkedLeadId;document.querySelector('#customerContractState').textContent=`${contracts.length} ${contracts.length===1?'Vertrag':'Verträge'}`;document.querySelector('#customerOfficialDocuments').innerHTML=contracts.length?contracts.flatMap(contract=>{const contractUrl=contract.document_storage_path&&leadId?`/api/leads?action=contract-download&id=${encodeURIComponent(leadId)}&contractId=${encodeURIComponent(contract.id)}`:'',videoUrl=contract.video_recording_path&&leadId?`/api/leads?action=video-recording-download&id=${encodeURIComponent(leadId)}&contractId=${encodeURIComponent(contract.id)}`:'',isMeetRecording=contract.video_recording_provider==='google_meet';return[{title:contract.title||'Vertragsdokument',ready:Boolean(contract.document_confirmed_at),type:'Vertrag',date:contract.document_confirmed_at||contract.created_at,url:contractUrl,fileName:`${contract.contract_number||'FDD-Vertrag'}.pdf`,mimeType:'application/pdf'},{title:`Videovertrag · ${contract.title||'Vertragsabschluss'}`,ready:Boolean(contract.video_contract_confirmed_at),type:isMeetRecording?'Google-Meet-Videovertrag':'Videovertrag',date:contract.video_contract_confirmed_at||contract.created_at,url:videoUrl||contractUrl,fileName:videoUrl?`${contract.contract_number||'FDD-Videovertrag'}.${isMeetRecording?'mp4':'webm'}`:`${contract.contract_number||'FDD-Vertrag'}.pdf`,mimeType:videoUrl?(isMeetRecording?'video/mp4':'video/webm'):'application/pdf'}];}).map(item=>`<article class="${item.ready?'ready':'pending'} ${item.url?'is-previewable':''}"${item.url?customerDocumentPreviewAttributes(item):''}><span>${item.ready?'✓':'○'}</span><div><small>${escapeHtml(item.type)}</small><strong>${escapeHtml(item.title)}</strong><p>${item.ready?`Bestätigt am ${crmDate(item.date)}`:'Noch nicht vollständig bestätigt'}</p></div>${item.url?'<button type="button">Ansehen ↗</button>':''}</article>`).join(''):'<div class="empty">Noch keine Vertragsunterlagen vorhanden.</div>';document.querySelector('#customerDocumentCount').textContent=`${documents.length} ${documents.length===1?'Dokument':'Dokumente'}`;document.querySelector('#customerDocumentInbox').innerHTML=documents.length?documents.map(document=>customerDocumentMarkup(document,person)).join(''):'<div class="empty">Noch keine Uploads oder freigegebenen Unterlagen vorhanden.</div>';}
function clearCustomerDocumentPreview(){const frame=document.querySelector('#customerDocumentPreviewFrame'),image=document.querySelector('#customerDocumentPreviewImage');frame.src='about:blank';image.removeAttribute('src');}
function closeCustomerDocumentPreview(){const dialog=document.querySelector('#customerDocumentPreviewDialog');if(dialog.open)dialog.close();}
function openCustomerDocumentPreview(element){const dialog=document.querySelector('#customerDocumentPreviewDialog'),url=element.dataset.documentUrl,mime=(element.dataset.documentMime||'').toLowerCase(),file=(element.dataset.documentFile||'').toLowerCase(),isPdf=mime==='application/pdf'||file.endsWith('.pdf'),isImage=mime.startsWith('image/')||/\.(png|jpe?g|webp|gif)$/.test(file),isVideo=mime.startsWith('video/')||/\.(webm|mp4|mov)$/.test(file),frame=document.querySelector('#customerDocumentPreviewFrame'),image=document.querySelector('#customerDocumentPreviewImage'),fallback=document.querySelector('#customerDocumentPreviewFallback');[frame,image,fallback].forEach(item=>{item.hidden=true;});document.querySelector('#customerDocumentPreviewTitle').textContent=element.dataset.documentTitle||'Dokument ansehen';document.querySelector('#customerDocumentPreviewMeta').textContent=[element.dataset.documentFile,isPdf?'PDF-Dokument':isImage?'Bilddatei':isVideo?'Videoaufzeichnung':'Originaldatei'].filter(Boolean).join(' · ');const link=document.querySelector('#customerDocumentPreviewDownload');link.href=url;if(isPdf){frame.hidden=false;frame.src=`${url}#view=FitH`;}else if(isImage){image.hidden=false;image.src=url;image.alt=element.dataset.documentTitle||'Dokumentenvorschau';}else fallback.hidden=false;dialog.showModal();}
function renderCustomerFinance(data){const customer=data.customer||{},finance=customer.finance||data.leadDashboard?.finance||{contractTotal:0,paidTotal:0,openBalance:0},bank=customer.bankAccount,payments=customer.payments||[],contracts=customer.contracts||[];document.querySelector('#customerAccountState').textContent=finance.openBalance>0?'Saldo offen':'Ausgeglichen';document.querySelector('#customerAccountPage').innerHTML=`<section class="customer-finance-cards"><article><small>Vertragsvolumen</small><strong>${euro(finance.contractTotal)}</strong></article><article><small>Zahlungseingänge</small><strong>${euro(finance.paidTotal)}</strong></article><article class="${finance.openBalance>0?'open':'paid'}"><small>Offener Saldo</small><strong>${euro(finance.openBalance)}</strong></article></section><section class="customer-bank-data"><h3>Bankverbindung</h3>${bank?`<dl><div><dt>Kontoinhaber</dt><dd>${escapeHtml(bank.account_holder||'—')}</dd></div><div><dt>IBAN</dt><dd>${escapeHtml(bank.iban||'—')}</dd></div><div><dt>BIC</dt><dd>${escapeHtml(bank.bic||'—')}</dd></div><div><dt>Referenz</dt><dd>${escapeHtml(bank.payment_reference||'—')}</dd></div></dl>`:'<div class="empty">Noch keine Bankverbindung hinterlegt.</div>'}</section>`;document.querySelector('#customerBillingState').textContent=`${contracts.length} Verträge · ${payments.length} Zahlungen`;const entries=[...contracts.map(item=>({date:item.signed_at||item.created_at,title:item.title||'Vertrag',copy:`${contractStatusLabels[item.status]||item.status} · ${euro(item.amount)}`,tone:'contract'})),...payments.map(item=>({date:item.booked_at||item.created_at,title:'Zahlungseingang',copy:`${euro(item.amount)} · ${item.reference||'ohne Referenz'}`,tone:'payment'}))].sort((a,b)=>new Date(b.date)-new Date(a.date));document.querySelector('#customerBillingPage').innerHTML=entries.length?entries.map(item=>`<article class="${item.tone}"><span>${item.tone==='payment'?'€':'▤'}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.copy)}</p></div><time>${crmDate(item.date)}</time></article>`).join(''):'<div class="empty">Noch keine Rechnungs- oder Zahlungsdaten vorhanden.</div>';}
function renderCustomerMessages(data){const communications=data.customer?.communications||data.leadDashboard?.communications||[],visible=communications.filter(item=>item.channel!=='whatsapp'||item.direction==='outbound');document.querySelector('#customerMessageCount').textContent=`${visible.length} ${visible.length===1?'Nachricht':'Nachrichten'}`;document.querySelector('#customerMessagePage').innerHTML=visible.length?visible.map(item=>`<article><span class="${escapeHtml(item.direction)}">${item.channel==='whatsapp'?'WA':'@'}</span><div><strong>${escapeHtml(item.subject||'Nachricht')}</strong><p>${escapeHtml(item.body||item.preview||'Kein Nachrichtentext')}</p><small>${item.direction==='inbound'?'Eingang':'Ausgang'} · ${crmDate(item.occurred_at)}</small></div></article>`).join(''):'<div class="empty">Noch keine Kundenkommunikation vorhanden.</div>';const whatsapp=communications.filter(item=>item.channel==='whatsapp'),profile=data.customer?.profile||data.program.profile;document.querySelector('#customerWhatsappState').textContent=data.customer?.integrations?.whatsapp?.configured?'WhatsApp verbunden':'WhatsApp noch nicht verbunden';document.querySelector('#customerWhatsappState').classList.toggle('active',Boolean(data.customer?.integrations?.whatsapp?.configured));document.querySelector('#customerWhatsappName').textContent=profile.name;document.querySelector('#customerWhatsappNumber').textContent=profile.whatsapp_phone||(profile.whatsapp_same_as_mobile?profile.mobile_phone:'')||'Keine WhatsApp-Nummer';document.querySelector('#customerWhatsappAvatar').textContent=data.person.initials;document.querySelector('#customerWhatsappMessages').innerHTML=whatsapp.length?whatsapp.slice().reverse().map(item=>`<article class="${escapeHtml(item.direction)}"><p>${escapeHtml(item.body||item.preview||'')}</p><small>${crmDate(item.occurred_at)} · ${item.direction==='outbound'?'Ausgang':'Eingang'}</small></article>`).join(''):'<div class="customer-phone-empty">Noch keine WhatsApp-Nachrichten.</div>';const phoneMessages=document.querySelector('#customerWhatsappMessages');phoneMessages.scrollTop=phoneMessages.scrollHeight;document.querySelector('#customerWhatsappForm').querySelector('[type="submit"]').disabled=!data.customer?.integrations?.whatsapp?.configured;}
function renderCustomerAppointments(data){const appointments=data.customer?.appointments||[],now=Date.now(),upcoming=appointments.filter(item=>item.status==='scheduled'&&new Date(item.starts_at).getTime()>=now),past=appointments.filter(item=>!upcoming.includes(item));document.querySelector('#customerAppointmentState').textContent=upcoming.length?`${upcoming.length} bevorstehend`:'Kein Termin geplant';const group=(title,items)=>`<section><h3>${title}</h3>${items.length?items.map(item=>`<article><time><b>${new Date(item.starts_at).toLocaleDateString('de-DE',{day:'2-digit',month:'short'})}</b><span>${new Date(item.starts_at).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})} Uhr</span></time><div><strong>${escapeHtml(item.title||'Kundentermin')}</strong><p>${escapeHtml(item.source==='google_calendar'?'Google Kalender':'CRM-Termin')} · ${escapeHtml(item.status==='cancelled'?'Abgesagt':item.status==='completed'?'Abgeschlossen':'Geplant')}</p></div><nav>${item.meet_url?`<a href="${escapeHtml(item.meet_url)}" target="_blank" rel="noopener">Meet öffnen ↗</a>`:''}${item.google_event_url?`<a href="${escapeHtml(item.google_event_url)}" target="_blank" rel="noopener">Kalender ↗</a>`:''}</nav></article>`).join(''):'<div class="empty">Keine Termine in diesem Bereich.</div>'}</section>`;document.querySelector('#customerAppointmentPage').innerHTML=group('Nächste Termine',upcoming)+group('Vergangene Termine',past.slice().reverse());}
function customerClarityFindingMarkup(item){return`<article><div><strong>${escapeHtml(item.title||'Ergebnis')}</strong><span>${(item.weekRefs||[]).map(week=>`W${Number(week)}`).join(' · ')}</span></div><p>${escapeHtml(item.finding||'')}</p><details><summary>Belege aus dem Prozess</summary><ul>${(item.evidence||[]).map(value=>`<li>${escapeHtml(value)}</li>`).join('')}</ul></details></article>`;}
function renderCustomerClarity(data){const analysis=data.program?.clarityAnalysis||{},trajectory=analysis.clarityTrajectory||{},start=Number.isInteger(trajectory.start)?trajectory.start:null,current=Number.isInteger(trajectory.current)?trajectory.current:null,change=Number.isInteger(trajectory.change)?trajectory.change:null;document.querySelector('#customerClarityHeadline').textContent=analysis.headline||'Analyse startet mit den ersten Kundeneingaben';document.querySelector('#customerClaritySummary').textContent=analysis.executiveSummary||'Noch keine freigegebenen Prozessdaten vorhanden.';document.querySelector('#customerClarityFocus').textContent=analysis.currentFocus||'Zuerst die aktuelle Ausgangslage offen erkunden.';document.querySelector('#customerClarityScore').innerHTML=`<small>Klarheitsverlauf</small><strong>${start!==null?start:'—'} → ${current!==null?current:'—'}</strong><span>${change!==null?`${change>=0?'+':''}${change} ${Math.abs(change)===1?'Punkt':'Punkte'}`:'Noch keine Vergleichsmessung'}</span><p>${escapeHtml(trajectory.interpretation||'')}</p>`;const sourceWeeks=analysis.sourceWeeks||[];document.querySelector('#customerClaritySource').textContent=sourceWeeks.length?`Datenbasis: ${sourceWeeks.map(week=>`Woche ${week}`).join(', ')}`:'Noch keine freigegebenen Eingaben';document.querySelector('#customerClarityGenerated').textContent=analysis.generatedAt?`${analysis.generator==='openai'?'KI-Analyse':'Beleggebundene Basisanalyse'} · ${new Date(analysis.generatedAt).toLocaleString('de-DE')}`:'Analyse wird mit den ersten Eingaben erzeugt';document.querySelector('#customerClarityThemes').innerHTML=(analysis.themes||[]).length?analysis.themes.map(customerClarityFindingMarkup).join(''):'<div class="customer-clarity-empty">Noch keine wiederkehrenden Themen belastbar erkennbar.</div>';document.querySelector('#customerClarityTensions').innerHTML=(analysis.tensions||[]).length?analysis.tensions.map(customerClarityFindingMarkup).join(''):'<div class="customer-clarity-empty">Noch kein Spannungsfeld ausreichend belegt.</div>';document.querySelector('#customerClarityQuestions').innerHTML=(analysis.openQuestions||[]).length?`<h4>Offene Fragen fürs Gespräch</h4>${analysis.openQuestions.map((question,index)=>`<div><span>${index+1}</span><p>${escapeHtml(question)}</p></div>`).join('')}`:'';const labels={meet:['Google Meet','M'],phone:['Telefon','☎'],whatsapp:['WhatsApp','WA']},guidance=analysis.conversationGuidance||{};document.querySelector('#customerClarityGuidance').innerHTML=Object.entries(labels).map(([channel,[label,icon]])=>`<section class="channel-${channel}"><header><span>${icon}</span><div><small>Gesprächskanal</small><h4>${label}</h4></div></header>${(guidance[channel]||[]).map((item,index)=>`<article><p>${escapeHtml(item.prompt)}</p><small>${escapeHtml(item.reason)}</small><div><button type="button" data-copy-clarity-text data-clarity-channel="${channel}" data-clarity-index="${index}">Text kopieren</button>${channel==='whatsapp'?`<button type="button" data-use-clarity-whatsapp="${index}">In WhatsApp vorbereiten →</button>`:''}</div></article>`).join('')}</section>`).join('');document.querySelector('#customerClarityBoundaries').innerHTML=(analysis.boundaries||[]).map(value=>`<span>✓ ${escapeHtml(value)}</span>`).join('');}
function renderCustomerDashboard(data){const {person,program,leadDashboard,customer}=data,profile=customer?.profile||program.profile,progress=person.progress||0,photo=profile.photoUrl||'',processWeek=customerProcessWeek(program),processDefinition=gateData.find(item=>Number(item.week)===processWeek),phaseLabel=processWeek?`Woche ${processWeek} · ${processDefinition?.title||'Aktueller Prozessschritt'}`:'Onboarding';document.querySelector('#customerDashboardInitials').innerHTML=photo?`<img src="${escapeHtml(photo)}" alt="Profilbild von ${escapeHtml(profile.name)}">`:escapeHtml(person.initials);document.querySelector('#customerDashboardName').textContent=profile.name;document.querySelector('#customerDashboardPhase').textContent=phaseLabel;document.querySelector('#customerDashboardContact').textContent=[profile.customer_number||person.customerNumber,profile.birth_date?`geb. ${new Date(`${profile.birth_date}T00:00:00`).toLocaleDateString('de-DE')}`:'Geburtsdatum offen',profile.email].filter(Boolean).join(' · ');document.querySelector('#customerProgramHeadline').textContent=processWeek?`Woche ${processWeek} von 8 · ${processDefinition?.title||profile.name}`:'Onboarding · Wochenprozess noch nicht gestartet';document.querySelector('#customerProgramProgress').textContent=`${progress} % abgeschlossen`;const weeks=customerWeekMarkup(program);document.querySelector('#customerWeekTrack').innerHTML=weeks;document.querySelector('#customerSummaryContact').innerHTML=customerContactMarkup(profile,{compact:true,editable:true});document.querySelector('#customerDataPage').innerHTML=customerContactMarkup(profile,{editable:true});const finance=customer?.finance||leadDashboard?.finance||{openBalance:0};document.querySelector('#customerOpenBalance').textContent=euro(finance.openBalance);document.querySelector('#customerBalanceState').textContent=finance.openBalance>0?'Zahlung oder Restbetrag noch offen':'Keine offenen Forderungen';const customerCommunications=customer?.communications||leadDashboard?.communications||[],communicationCount=customerCommunications.filter(item=>item.channel!=='whatsapp'||item.direction==='outbound').length,openTasks=(leadDashboard?.tasks||[]).filter(item=>!item.completed).length,openQuestions=(leadDashboard?.questions||[]).filter(item=>item.status==='open').length;document.querySelector('#customerCommunicationSummary').innerHTML=`<strong>${communicationCount}</strong><span>${communicationCount===1?'Nachricht dokumentiert':'Nachrichten dokumentiert'}</span>`;document.querySelector('#customerTaskSummary').innerHTML=`<strong>${openTasks+openQuestions}</strong><span>${openTasks} Aufgaben · ${openQuestions} Kundenfragen offen</span>`;document.querySelector('#customerLoginPage').innerHTML=`<dl class="customer-contact-data"><div><dt>Kundennummer</dt><dd>${escapeHtml(person.customerNumber||'Wird vergeben')}</dd></div><div><dt>Portal-Login</dt><dd>${escapeHtml(person.loginName||'Wird automatisch erzeugt')}</dd></div><div><dt>Zugangsstatus</dt><dd>${escapeHtml(participantLoginStatus(person)[0])}</dd></div><div><dt>E-Mail</dt><dd>${escapeHtml(person.email)}</dd></div></dl><div class="customer-login-actions"><button type="button" class="primary" data-manage-customer-login>Login & Passwort verwalten</button><p>Ein neu erzeugtes Einmalpasswort ist nur einmal sichtbar und zwingt beim nächsten Login zur persönlichen Passwortvergabe. Der Kunde kann zusätzlich im Portal jederzeit „Passwort vergessen“ nutzen.</p></div>`;renderCustomerProcess(data);renderCustomerClarity(data);renderCustomerConversation(data);renderCustomerDocuments(data);renderCustomerFinance(data);renderCustomerMessages(data);renderCustomerAppointments(data);setCustomerDashboardPage(customerDashboardPage,false);renderContextNavigation('participants');}
function setCustomerDashboardPage(page,syncNavigation=true){const allowed=['dashboard','data','conversation','program','clarity','login','documents','documentInbox','account','billing','messages','whatsapp','appointments'];if(!allowed.includes(page)||!canAccessCustomerPage(page))page='dashboard';customerDashboardPage=page;document.querySelector('#openCustomerProgram').hidden=!activeStaffPermissions.includes('program');document.querySelector('#openCustomerLogin').hidden=!activeStaffPermissions.includes('customers');document.querySelector('#openCustomerPortal').hidden=!activeStaffPermissions.some(permission=>['customers','program'].includes(permission));document.querySelectorAll('[data-customer-summary-permission]').forEach(card=>{card.hidden=!activeStaffPermissions.includes(card.dataset.customerSummaryPermission);});document.querySelectorAll('[data-customer-page]').forEach(section=>{const active=section.dataset.customerPage===page;section.hidden=!active;section.classList.toggle('active',active);});if(syncNavigation&&activeCustomerDashboard)renderContextNavigation('participants');window.scrollTo({top:0,behavior:'smooth'});}
async function openCustomerDashboard(participantId,page='dashboard'){const person=participants.find(item=>item.id===participantId);if(!person)return toast('Kunde wurde nicht gefunden.');participantSection='overview';customerDashboardPage=page;document.querySelector('#participantOverview').hidden=true;document.querySelector('#participantLoginManager').hidden=true;document.querySelector('#customerDashboard').hidden=false;document.querySelector('#customerDashboardName').textContent='Kundenakte wird geladen …';activeCustomerDashboard={person,program:null,leadDashboard:null,customer:null};renderContextNavigation('participants');try{const linkedLeadId=person.linkedLeadId||leads.find(item=>item.converted_user_profile_id===participantId)?.id;const [programResponse,leadResponse,customerResponse]=await Promise.all([fetch(`/api/program-control?participantId=${encodeURIComponent(participantId)}`),linkedLeadId?fetch(`/api/leads?action=dashboard&id=${encodeURIComponent(linkedLeadId)}`):Promise.resolve(null),fetch(`/api/customer-records?action=overview&participantId=${encodeURIComponent(participantId)}`)]);const program=await programResponse.json(),customer=await customerResponse.json();if(!programResponse.ok)throw new Error(program.error);if(!customerResponse.ok)throw new Error(customer.error);let leadDashboard=null;if(leadResponse){leadDashboard=await leadResponse.json();if(!leadResponse.ok)throw new Error(leadDashboard.error);}customerProcessSelectedWeek=customerProcessWeek(program)||1;activeCustomerDashboard={person,program,leadDashboard,customer};renderCustomerDashboard(activeCustomerDashboard);}catch(error){resetCustomerListView();renderContextNavigation('participants');toast(error.message||'Kunden-Dashboard konnte nicht geladen werden.');}}
function openAdminWeekReflection(week){const item=activeCustomerDashboard?.program?.processWeeks?.find(entry=>Number(entry.week)===Number(week));if(!item?.reflection)return;let dialog=document.querySelector('#adminWeekReflectionDialog');if(!dialog){document.body.insertAdjacentHTML('beforeend','<dialog id="adminWeekReflectionDialog" class="admin-week-reflection-dialog"><div class="admin-week-reflection-shell"><button type="button" class="dialog-close" data-close-admin-reflection>×</button><p class="eyebrow" id="adminReflectionEyebrow"></p><h2 id="adminReflectionTitle"></h2><p id="adminReflectionSummary"></p><div id="adminReflectionHighlights"></div><div class="admin-reflection-grid"><article><small>Entwicklung</small><p id="adminReflectionDevelopment"></p></article><article><small>Nächster Impuls</small><p id="adminReflectionImpulse"></p></article></div><blockquote id="adminReflectionClosing"></blockquote><section><small>Fragen für das Q&amp;A mit Markus</small><div id="adminReflectionQuestions"></div></section></div></dialog>');dialog=document.querySelector('#adminWeekReflectionDialog');dialog.addEventListener('click',event=>{if(event.target===dialog||event.target.closest('[data-close-admin-reflection]'))dialog.close();});}const reflection=item.reflection,questions=(activeCustomerDashboard?.leadDashboard?.questions||[]).filter(question=>Number(question.week)===Number(week));document.querySelector('#adminReflectionEyebrow').textContent=`Kundenakte · Wochenreflexion ${week}`;document.querySelector('#adminReflectionTitle').textContent=reflection.title||`Reflexion zu Woche ${week}`;document.querySelector('#adminReflectionSummary').textContent=reflection.summary||'';document.querySelector('#adminReflectionHighlights').innerHTML=`<ul>${(reflection.highlights||[]).map(value=>`<li>${escapeHtml(value)}</li>`).join('')}</ul>`;document.querySelector('#adminReflectionDevelopment').textContent=reflection.development||'';document.querySelector('#adminReflectionImpulse').textContent=reflection.nextImpulse||'';document.querySelector('#adminReflectionClosing').textContent=reflection.closing||'';document.querySelector('#adminReflectionQuestions').innerHTML=questions.length?questions.map(question=>`<article><b>${escapeHtml(question.question)}</b><span>${question.status==='answered'?'Beantwortet':'Offen'} · ${crmDate(question.created_at)}</span></article>`).join(''):'<p>Noch keine Frage für das persönliche Wochen-Q&amp;A gestellt.</p>';dialog.showModal();}
document.querySelector('#customerProcessWeekNav')?.addEventListener('click',event=>{const button=event.target.closest('[data-customer-process-week]');if(!button||!activeCustomerDashboard)return;customerProcessSelectedWeek=Number(button.dataset.customerProcessWeek);renderCustomerProcess(activeCustomerDashboard);const item=activeCustomerDashboard.program?.processWeeks?.find(entry=>Number(entry.week)===customerProcessSelectedWeek);if(item?.reflection)openAdminWeekReflection(customerProcessSelectedWeek);});
function closeCustomerDashboard(){resetCustomerListView();renderParticipants();renderContextNavigation('participants');window.scrollTo({top:0,behavior:'smooth'});}

function dashboardNumber(value,digits=0){return Number(value||0).toLocaleString('de-DE',{minimumFractionDigits:digits,maximumFractionDigits:digits});}
function renderDashboardClarity(clarity={}){const phases=clarity.phases||[],positions=[6,50,94],labels={start:'Start',midpoint:'Halbzeit',end:'Ende'};const points=phases.map((item,index)=>item.average===null||item.average===undefined?null:{...item,x:positions[index],y:10+Number(item.average)*8}).filter(Boolean);document.querySelector('#dashboardClarityLine').setAttribute('points',points.map(item=>`${item.x},${100-item.y}`).join(' '));document.querySelector('#dashboardClarityPoints').innerHTML=points.map(item=>`<span style="left:${item.x}%;bottom:${item.y}%">${dashboardNumber(item.average,1)}<small>${escapeHtml(labels[item.phase]||item.phase)} · ${item.count}</small></span>`).join('');document.querySelector('#dashboardClarityEmpty').hidden=points.length>0;const hasGain=clarity.averageGain!==null&&clarity.averageGain!==undefined;document.querySelector('#dashboardClarityGain').textContent=hasGain?`${Number(clarity.averageGain)>=0?'+':''}${dashboardNumber(clarity.averageGain,1)}`:'—';document.querySelector('#dashboardClarityCopy').textContent=clarity.completedComparisons?`${clarity.completedComparisons} vollständige Start-/Endmessung${clarity.completedComparisons===1?'':'en'} · Skala 1–10`:'Noch keine vollständige Start-/Endmessung';}
function renderDashboardDistribution(values=[],onboarding=0){const counts=Array.from({length:8},(_,index)=>Number(values[index]||0)),maximum=Math.max(1,...counts);document.querySelector('#dashboardWeekCounts').innerHTML=counts.map(value=>`<i style="height:${Math.max(25,25+value/maximum*70)}px">${value}</i>`).join('');document.querySelector('#dashboardWeekLabels').innerHTML=counts.map((value,index)=>`<span class="${value===maximum&&value>0?'current':''}">${index+1}</span>`).join('');document.querySelector('#dashboardOnboardingCount').textContent=`${Number(onboarding||0)} ${Number(onboarding)===1?'Kunde':'Kunden'} im Onboarding`;document.querySelectorAll('.metrics article.dark .bars i').forEach((bar,index)=>{bar.style.height=`${Math.max(12,counts[index]/maximum*100)}%`;});}
function openDashboardAction(item){if(!item?.entityId)return;if(item.entityType==='participant'){showView('participants');openCustomerDashboard(item.entityId);}else if(item.entityType==='lead'){showView('leads');openLeadDashboard(item.entityId);}}
function renderDashboardAttention(attention={}){const list=document.querySelector('#dashboardAttentionList'),items=attention.items||[];document.querySelector('#dashboardAttentionCount').textContent=String(attention.total||0);list.innerHTML=items.length?items.map(item=>`<article data-dashboard-action="${escapeHtml(item.id)}"><i class="${escapeHtml(item.tone||'orange')}">${escapeHtml(item.icon||'!')}</i><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.subtitle)}</p></div><button type="button">${escapeHtml(item.actionLabel||'Öffnen')}</button></article>`).join(''):'<div class="empty">Aktuell gibt es keine offenen Vorgänge. Alles im grünen Bereich.</div>';list.querySelectorAll('[data-dashboard-action]').forEach(element=>element.addEventListener('click',()=>openDashboardAction(items.find(item=>item.id===element.dataset.dashboardAction))));}
function safeDashboardUrl(value){try{const url=new URL(value);return url.protocol==='https:'?url.href:'';}catch{return'';}}
function renderDashboardAppointments(items=[]){const list=document.querySelector('#dashboardAppointmentList'),count=document.querySelector('#dashboardAppointmentCount');count.textContent=`${items.length} ${items.length===1?'Termin':'Termine'}`;list.innerHTML=items.length?items.map(item=>{const start=new Date(item.startsAt),end=item.endsAt?new Date(item.endsAt):null,meet=safeDashboardUrl(item.meetUrl),calendar=safeDashboardUrl(item.calendarUrl),initials=(item.name||'Interessent').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();return`<article data-dashboard-appointment="${escapeHtml(item.id)}"><time datetime="${escapeHtml(item.startsAt)}"><b>${start.toLocaleDateString('de-DE',{day:'2-digit',month:'short',timeZone:'Europe/Berlin'})}</b><span>${start.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'})} Uhr${end?` · bis ${end.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'})}`:''}</span></time><span class="dashboard-appointment-avatar">${escapeHtml(initials||'IN')}</span><div class="dashboard-appointment-person"><strong>${escapeHtml(item.name||'Interessent')}</strong><small>${escapeHtml([item.email,item.phone].filter(Boolean).join(' · ')||'Kontaktdaten in der Akte')}</small><i>Online-Erstkontakt · ${escapeHtml(leadStatusLabels[item.status]||item.status||'Geplant')}</i></div><nav>${meet?`<a href="${escapeHtml(meet)}" target="_blank" rel="noopener" data-dashboard-meet>Meet öffnen ↗</a>`:''}${calendar?`<a href="${escapeHtml(calendar)}" target="_blank" rel="noopener" data-dashboard-calendar>Kalender ↗</a>`:''}<button type="button">Akte öffnen →</button></nav></article>`;}).join(''):'<div class="dashboard-appointment-empty"><span>✓</span><div><strong>Keine anstehenden Erstgespräche</strong><p>Neue Buchungen von der Landingpage erscheinen hier automatisch.</p></div></div>';list.querySelectorAll('[data-dashboard-appointment]').forEach(row=>row.addEventListener('click',event=>{if(event.target.closest('a'))return;openDashboardAction({entityType:'lead',entityId:row.dataset.dashboardAppointment});}));}
function renderCommandDashboard(data){const generated=new Date(data.generatedAt||Date.now()),hour=generated.getHours(),firstName=(data.adminName||'Markus').trim().split(/\s+/)[0],appointments=data.upcomingAppointments||[];document.querySelector('#dashboardDate').textContent=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(generated);document.querySelector('#dashboardGreeting').textContent=`${hour<11?'Guten Morgen':hour<18?'Guten Tag':'Guten Abend'}, ${firstName}.`;const summary=data.summary||{};document.querySelector('#dashboardLiveSummary').textContent=`${summary.activeLeads||0} Interessenten · ${appointments.length} anstehende ${appointments.length===1?'Termin':'Termine'} · ${summary.unreadMessages||0} ungelesene Nachrichten`;document.querySelector('#activeCustomerCount').textContent=String(summary.activeCustomers||0);document.querySelector('#dashboardNewCustomers').textContent=`+${summary.newCustomers||0} diesen Monat`;document.querySelector('#dashboardOpenGates').textContent=String(summary.openGates||0);document.querySelector('#dashboardOpenGateCopy').textContent=summary.openGates?`${summary.overdueGates||0} davon ohne Aktivität seit über 48 Stunden`:'Keine offenen Pflichtschritte';renderDashboardClarity(data.clarity);renderDashboardDistribution(data.weekDistribution,summary.onboarding);renderDashboardAttention(data.attention);renderDashboardAppointments(appointments);}
async function loadCommandDashboard(){try{const response=await fetch('/api/leads?action=command-dashboard'),data=await response.json();if(!response.ok)throw new Error(data.error);renderCommandDashboard(data);}catch(error){document.querySelector('#dashboardLiveSummary').textContent='Live-Daten konnten nicht geladen werden';document.querySelector('#dashboardAttentionList').innerHTML=`<div class="empty system-error">${escapeHtml(error.message||'Dashboard konnte nicht geladen werden.')}</div>`;}}
function participantLoginStatus(person){if(person.mustChangePassword)return['Einmalpasswort aktiv','change'];if(person.passwordChangedAt)return['Persönliches Passwort','active'];return['Einrichtung offen','pending'];}
function renderParticipantLogins(){const rows=document.querySelector('#participantLoginRows');if(!rows)return;document.querySelector('#participantLoginCount').textContent=`${participants.length} ${participants.length===1?'Zugang':'Zugänge'}`;rows.innerHTML=participants.length?participants.map(person=>{const [label,tone]=participantLoginStatus(person);return `<div class="participant-login-row"><div class="participant"><span class="avatar">${escapeHtml(person.initials)}</span><div><strong>${escapeHtml(person.name)}</strong><small>${escapeHtml(person.email)}</small></div></div><strong>${escapeHtml(person.customerNumber||'Wird vergeben')}</strong><code>${escapeHtml(person.loginName||'Wird automatisch erzeugt')}</code><span class="login-state ${tone}">${escapeHtml(label)}</span><button type="button" class="user-manage" data-manage-participant-login="${escapeHtml(person.id)}">Verwalten →</button></div>`;}).join(''):'<div class="empty">Noch keine Teilnehmer-Zugänge vorhanden.</div>';rows.querySelectorAll('[data-manage-participant-login]').forEach(button=>button.addEventListener('click',()=>openParticipantLogin(button.dataset.manageParticipantLogin)));}
