const customerProfileFieldLabels={name:'Name',birthDate:'Geburtsdatum',street:'Anschrift',email:'E-Mail',phone:'Telefon',mobilePhone:'Mobilnummer',whatsappPhone:'WhatsApp'};
function openCustomerProfileEditor(field=''){
  const profile=activeCustomerDashboard?.customer?.profile||activeCustomerDashboard?.program?.profile,person=activeCustomerDashboard?.person;
  if(!profile||!person)return toast('Die Kundendaten sind noch nicht geladen.');
  customerProfileForm.elements.participantId.value=person.id;
  customerProfileForm.elements.name.value=profile.name||'';
  customerProfileForm.elements.birthDate.value=profile.birth_date||'';
  customerProfileForm.elements.email.value=profile.email||'';
  customerProfileForm.elements.street.value=profile.street||'';
  customerProfileForm.elements.postalCode.value=profile.postal_code||'';
  customerProfileForm.elements.city.value=profile.city||'';
  customerProfileForm.elements.country.value=profile.country||'Deutschland';
  customerProfileForm.elements.phone.value=profile.phone||'';
  customerProfileForm.elements.mobilePhone.value=profile.mobile_phone||'';
  customerProfileForm.elements.whatsappPhone.value=profile.whatsapp_phone||'';
  customerProfileForm.elements.whatsappSameAsMobile.checked=profile.whatsapp_same_as_mobile===true;
  customerProfileForm.elements.whatsappPhone.disabled=profile.whatsapp_same_as_mobile===true;
  customerProfileForm.elements.preferredCommunicationChannel.value=profile.preferred_communication_channel||'email';
  customerProfileForm.elements.postalMailActive.checked=profile.postal_mail_active!==false;
  customerProfileRevision=0;customerProfilePersistedRevision=0;setAutosaveState('#customerProfileAutosaveStatus','saved','Alle Änderungen gespeichert');
  document.querySelector('#customerProfileDialogTitle').textContent=field&&customerProfileFieldLabels[field]?`${customerProfileFieldLabels[field]} bearbeiten`:'Kundendaten bearbeiten';
  customerProfileDialog.showModal();
  requestAnimationFrame(()=>customerProfileForm.elements[field||'name']?.focus());
}
