function customerProfilePayload(form=customerProfileForm){return{name:form.elements.name.value,email:form.elements.email.value,birthDate:form.elements.birthDate.value,street:form.elements.street.value,postalCode:form.elements.postalCode.value,city:form.elements.city.value,country:form.elements.country.value,phone:form.elements.phone.value,mobilePhone:form.elements.mobilePhone.value,whatsappPhone:form.elements.whatsappPhone.value,whatsappSameAsMobile:form.elements.whatsappSameAsMobile.checked,preferredCommunicationChannel:form.elements.preferredCommunicationChannel.value,postalMailActive:form.elements.postalMailActive.checked};}
let customerProfileAutosaveTimer=0,customerProfileRevision=0,customerProfilePersistedRevision=0,customerProfileSaveQueue=Promise.resolve();
function persistCustomerProfile(){
  clearTimeout(customerProfileAutosaveTimer);
  const revision=customerProfileRevision,participantId=customerProfileForm.elements.participantId.value,customerProfile=customerProfilePayload();
  if(!participantId||!customerProfile.name.trim())return Promise.resolve(false);
  customerProfileSaveQueue=customerProfileSaveQueue.catch(()=>{}).then(async()=>{
    setAutosaveState('#customerProfileAutosaveStatus','saving','Wird automatisch gespeichert …');
    const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId,customerProfile})}),data=await response.json();
    if(!response.ok)throw new Error(data.error);
    customerProfilePersistedRevision=Math.max(customerProfilePersistedRevision,revision);
    if(customerProfilePersistedRevision===customerProfileRevision)setAutosaveState('#customerProfileAutosaveStatus','saved','Alle Änderungen gespeichert');
    return true;
  }).catch(error=>{setAutosaveState('#customerProfileAutosaveStatus','error','Speichern fehlgeschlagen');throw error;});
  return customerProfileSaveQueue;
}
customerProfileForm.addEventListener('input',event=>{if(event.target.name==='participantId')return;customerProfileRevision+=1;setAutosaveState('#customerProfileAutosaveStatus','saving','Wird automatisch gespeichert …');clearTimeout(customerProfileAutosaveTimer);customerProfileAutosaveTimer=setTimeout(()=>persistCustomerProfile().catch(()=>{}),650);});
customerProfileForm.addEventListener('change',event=>{if(event.target.name==='participantId')return;customerProfileRevision+=1;setAutosaveState('#customerProfileAutosaveStatus','saving','Wird automatisch gespeichert …');clearTimeout(customerProfileAutosaveTimer);customerProfileAutosaveTimer=setTimeout(()=>persistCustomerProfile().catch(()=>{}),250);});
