const customerConversationForm=document.querySelector('#customerConversationForm');
let customerConversationAutosaveTimer=0,customerConversationRevision=0,customerConversationPersistedRevision=0,customerConversationSaveQueue=Promise.resolve();
function customerConversationPayload(){const lead=activeCustomerDashboard?.leadDashboard?.lead;if(!lead)return null;const[firstName,lastName]=splitLeadName(lead),mobilePhone=lead.mobile_phone||activeCustomerDashboard?.customer?.profile?.mobile_phone||lead.phone||'';return{id:lead.id,firstName:lead.first_name||firstName,lastName:lead.last_name||lastName,email:lead.email,mobilePhone,phone:lead.mobile_phone?lead.phone||'':'',whatsappSameAsMobile:lead.whatsapp_same_as_mobile!==false,whatsappPhone:lead.whatsapp_phone||mobilePhone,status:'customer',challenge:lead.challenge||'',internalNotes:customerConversationForm.elements.internalNotes.value,qualificationAnswers:Object.fromEntries(Array.from({length:6},(_,index)=>[`q${index+1}`,customerConversationForm.elements[`q${index+1}`]?.value||'']))};}
function persistCustomerConversation(){clearTimeout(customerConversationAutosaveTimer);const payload=customerConversationPayload(),revision=customerConversationRevision;if(!payload)return Promise.resolve(false);customerConversationSaveQueue=customerConversationSaveQueue.catch(()=>{}).then(async()=>{setAutosaveState('#customerConversationAutosaveStatus','saving','Wird automatisch gespeichert …');const response=await fetch('/api/leads?action=update',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error);activeCustomerDashboard.leadDashboard.lead=data.lead;updateLeadCache(data.lead);customerConversationPersistedRevision=Math.max(customerConversationPersistedRevision,revision);if(customerConversationPersistedRevision===customerConversationRevision)setAutosaveState('#customerConversationAutosaveStatus','saved','Alle Änderungen gespeichert');return true;}).catch(error=>{setAutosaveState('#customerConversationAutosaveStatus','error','Speichern fehlgeschlagen');throw error;});return customerConversationSaveQueue;}
