let gateSettingsLoaded=false;
function renderGateGrid(){const grid=document.querySelector('#gateGrid');grid.innerHTML=gateData.map((gate,index)=>`<article class="gate-card ${index<3?'complete':index===3?'current':''}" data-gate-week="${gate.week}"><div class="gate-top"><span>${Number(gate.week)===0?'Start':`Woche ${Number(gate.week)}`}</span><div class="gate-card-tools"><i>${index<3?'Abgeschlossen':index===3?'Aktiv':'Gesperrt'}</i><button type="button" class="gate-menu" data-edit-gate="${gate.week}" aria-label="${escapeHtml(gate.title)} bearbeiten" title="Gate bearbeiten"><span aria-hidden="true"><i></i><i></i><i></i></span></button></div></div><h2>${escapeHtml(gate.title)}</h2><p>${escapeHtml(gate.description)}</p><ul>${gate.items.map(item=>`<li><button type="button" data-edit-gate="${gate.week}" data-gate-key="${escapeHtml(item.gateKey)}"><span>${escapeHtml(item.label)}</span><small>Bearbeiten</small></button></li>`).join('')}</ul></article>`).join('');}
async function loadGateSettings(force=false){if(gateSettingsLoaded&&!force)return renderGateGrid();try{const response=await fetch('/api/gates?action=settings'),data=await response.json();if(!response.ok)throw new Error(data.error);gateData=data.weeks||gateData;gateSettingsLoaded=true;renderGateGrid();}catch(error){toast(error.message||'Wochen-Gates konnten nicht geladen werden.');renderGateGrid();}}
const gateSettingsDialog=document.querySelector('#gateSettingsDialog'),gateSettingsForm=document.querySelector('#gateSettingsForm');
function openGateSettings(week,fieldKey=''){const gate=gateData.find(item=>Number(item.week)===Number(week));if(!gate)return;gateSettingsForm.elements.week.value=String(gate.week);gateSettingsForm.elements.title.value=gate.title;gateSettingsForm.elements.description.value=gate.description;document.querySelector('#gateDialogWeek').textContent=Number(gate.week)===0?'Start · Onboarding':`Woche ${Number(gate.week)}`;document.querySelector('#gateFieldEditors').innerHTML=gate.items.map((item,index)=>`<div class="gate-field-editor"><span>${String(index+1).padStart(2,'0')}</span><label>Pflichtfeld ${index+1}<input name="gateLabel" data-gate-field-key="${escapeHtml(item.gateKey)}" value="${escapeHtml(item.label)}" minlength="2" maxlength="240" required><small>Die technische Gate-ID bleibt geschützt.</small></label></div>`).join('');gateSettingsDialog.showModal();const target=fieldKey?gateSettingsForm.querySelector(`[data-gate-field-key="${fieldKey}"]`):gateSettingsForm.elements.title;requestAnimationFrame(()=>target?.focus());}
async function saveGateSettings(action='save'){const button=gateSettingsForm.querySelector(action==='reset'?'[data-reset-gate]':'button[type="submit"]');button.disabled=true;try{const items=[...gateSettingsForm.querySelectorAll('[data-gate-field-key]')].map(input=>({gateKey:input.dataset.gateFieldKey,label:input.value.trim()}));const response=await fetch('/api/gates?action=settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({week:Number(gateSettingsForm.elements.week.value),title:gateSettingsForm.elements.title.value.trim(),description:gateSettingsForm.elements.description.value.trim(),items,action})}),data=await response.json();if(!response.ok)throw new Error(data.error);gateData=data.weeks||gateData;gateSettingsLoaded=true;renderGateGrid();gateSettingsDialog.close();toast(action==='reset'?'Gate-Standard wurde wiederhergestellt.':'Wochen-Gate wurde gespeichert.');}catch(error){toast(error.message||'Wochen-Gate konnte nicht gespeichert werden.');}finally{button.disabled=false;}}
renderGateGrid();
document.querySelector('#gateGrid').addEventListener('click',event=>{const button=event.target.closest('[data-edit-gate]');if(button)openGateSettings(button.dataset.editGate,button.dataset.gateKey||'');});
document.querySelectorAll('[data-close-gate-settings]').forEach(button=>button.addEventListener('click',()=>gateSettingsDialog.close()));
gateSettingsForm.addEventListener('submit',event=>{event.preventDefault();saveGateSettings();});
gateSettingsForm.querySelector('[data-reset-gate]').addEventListener('click',()=>{if(confirm('Dieses Wochen-Gate wirklich auf den ausgelieferten Standard zurücksetzen?'))saveGateSettings('reset');});

const selectedPermissions=form=>[...form.querySelectorAll('[name="permissions"]:checked')].map(input=>input.value);
const userDialog=document.querySelector('#userDialog');document.querySelector('#openUser').addEventListener('click',()=>userDialog.showModal());document.querySelectorAll('[data-close-user]').forEach(b=>b.addEventListener('click',()=>userDialog.close()));document.querySelector('#userForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form));values.permissions=selectedPermissions(form);const response=await fetch('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const data=await response.json();if(!response.ok)return toast(data.error);userDialog.close();form.reset();toast(data.passwordResetSent?'Benutzer angelegt. Passwort-E-Mail wurde versendet.':'Benutzer mit Startpasswort wurde angelegt.');loadUsers();});
const userEditDialog=document.querySelector('#userEditDialog');const userEditForm=document.querySelector('#userEditForm');document.querySelectorAll('[data-close-user-edit]').forEach(button=>button.addEventListener('click',()=>userEditDialog.close()));
function openUserEdit(id){const user=users.find(item=>item.id===id);if(!user)return;const participant=Boolean(user.participant_progress?.length);userEditForm.elements.id.value=user.id;userEditForm.elements.role.value=user.role;userEditForm.elements.status.value=user.status;userEditForm.elements.staffRole.value=user.staff_role||'';document.querySelector('#editUserName').textContent=user.name;document.querySelector('#editUserEmail').textContent=user.email;userEditForm.querySelectorAll('[name="permissions"]').forEach(input=>{input.checked=(user.permissions||[]).includes(input.value);if(input.value==='clara_program'){input.disabled=!participant;input.closest('label').title=participant?'Teilnehmerzugang aus einem bestätigten Vertrag':'Wird erst nach bestätigtem Lead-Vertragsabschluss freigeschaltet';}});userEditDialog.showModal();}
userEditForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const payload={id:form.elements.id.value,role:form.elements.role.value,staffRole:form.elements.role.value==='admin'?form.elements.staffRole.value:'',status:form.elements.status.value,permissions:selectedPermissions(form)};const response=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)return toast(data.error);userEditDialog.close();toast('Rolle und Benutzerrechte wurden gespeichert.');loadUsers();});
document.querySelector('#resetUserPassword').addEventListener('click',async()=>{const response=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:userEditForm.elements.id.value,action:'password_reset'})});const data=await response.json();toast(response.ok?'Passwort-Reset wurde per E-Mail versendet.':data.error);});

const programDialog=document.querySelector('#programDialog');
document.querySelectorAll('[data-close-program]').forEach(button=>button.addEventListener('click',()=>programDialog.close()));
function renderProgramControl(data){
  programSnapshot=data;
  document.querySelector('#programParticipantId').value=data.profile.id;
  document.querySelector('#programParticipantName').textContent=data.profile.name;
  document.querySelector('#programParticipantEmail').textContent=data.profile.email;
  document.querySelector('#customerProfileName').value=data.profile.name||'';
  document.querySelector('#customerProfileEmail').value=data.profile.email||'';
  document.querySelector('#customerBirthDate').value=data.profile.birth_date||'';
  document.querySelector('#customerStreet').value=data.profile.street||'';
  document.querySelector('#customerPostalCode').value=data.profile.postal_code||'';
  document.querySelector('#customerCity').value=data.profile.city||'';
  document.querySelector('#customerCountry').value=data.profile.country||'Deutschland';
  document.querySelector('#customerPhone').value=data.profile.phone||'';
  document.querySelector('#customerMobilePhone').value=data.profile.mobile_phone||'';
  document.querySelector('#customerWhatsappPhone').value=data.profile.whatsapp_phone||'';
  document.querySelector('#customerWhatsappSame').checked=data.profile.whatsapp_same_as_mobile===true;
  document.querySelector('#customerWhatsappPhone').disabled=data.profile.whatsapp_same_as_mobile===true;
  document.querySelector('#customerPreferredChannel').value=data.profile.preferred_communication_channel||'email';
  document.querySelector('#customerPostalActive').checked=data.profile.postal_mail_active!==false;
  document.querySelector('#customerPostalState').textContent=data.profile.postal_mail_active!==false?'Postanschrift aktiv':'Postanschrift inaktiv';
  document.querySelector('#programStartDate').value=data.access.programStartDate||new Date().toISOString().slice(0,10);
  document.querySelector('#programStatus').value=data.access.status;
  document.querySelector('#programCurrentWeek').value=data.access.processWeek?`Woche ${data.access.processWeek}`:'Onboarding';
  const releasedThrough=data.access.currentWeek?`bis Woche ${data.access.currentWeek}`:'noch keine Woche';
  document.querySelector('#programCalculatedWeek').textContent=data.access.status==='paused'?`Arbeitsstand: Woche ${data.access.processWeek||'—'} · Programm pausiert`:`Arbeitsstand: Woche ${data.access.processWeek||'—'} · Zeitplan freigegeben ${releasedThrough}`;
  document.querySelector('#programAccessBadge').textContent='Automatisch · 7 Tage';
  const grouped=Object.groupBy?Object.groupBy(data.gates,gate=>gate.week):data.gates.reduce((result,gate)=>{(result[gate.week]||=[]).push(gate);return result;},{});
  document.querySelector('#programGateList').innerHTML=Object.entries(grouped).map(([week,gates])=>{
    const released=Number(week)===0||(data.access.automaticUnlockedWeeks||[]).includes(Number(week));
    const scheduleNote=released?'':`<small>Zeitlich gesperrt bis ${escapeHtml(data.access.weekStates?.find(item=>Number(item.week)===Number(week))?.unlocksAt||'zum Freischaltungsdatum')}</small>`;
    return `<div class="gate-correction-week"><strong>${Number(week)===0?'Onboarding':`Woche ${week}`}</strong>${scheduleNote}${gates.map(gate=>`<label><input type="checkbox" data-correction-gate="${gate.id}" data-original="${Boolean(gate.completed_at)}" ${gate.completed_at?'checked':''} ${!released&&!gate.completed_at?'disabled':''}> ${escapeHtml(gate.label)}</label>`).join('')}</div>`;
  }).join('');
  const confirmations=data.technicalConfirmations||[];
  const reached=confirmations.filter(item=>item.status!=='not_reached');
  document.querySelector('#technicalConfirmationList').innerHTML=reached.length?reached.map(item=>item.status==='confirmed'
    ?`<article class="technical-confirmation confirmed"><div><span>Woche ${item.week}</span><strong>✓ ${escapeHtml(item.title)}</strong><small>Bestätigt ${item.confirmation?.confirmedAt?new Date(item.confirmation.confirmedAt).toLocaleString('de-DE'):''}</small></div>${item.confirmation?.resultReference?`<p>Referenz: ${escapeHtml(item.confirmation.resultReference)}</p>`:''}</article>`
    :`<article class="technical-confirmation pending" data-technical-card><div><span>Woche ${item.week} · wartet auf Admin-Prüfung</span><strong>${escapeHtml(item.title)}</strong><small>Der Kunde kann diesen Schritt nicht selbst freischalten.</small></div><label>Ergebnis / Referenz<input data-technical-reference placeholder="z. B. Bericht-ID, Termin oder Ablageort"></label><label>Prüfvermerk<textarea data-technical-note rows="3" placeholder="Was wurde geprüft und bestätigt?"></textarea></label><button type="button" class="primary" data-confirm-technical data-week="${item.week}" data-step-id="${escapeHtml(item.stepId)}">Geprüft und sicher bestätigen</button></article>`).join('')
    :'<div class="technical-empty">Aktuell wartet kein externer Journey-Schritt auf eine Admin-Bestätigung.</div>';
}

document.querySelector('#technicalConfirmationList').addEventListener('click',async event=>{
  const button=event.target.closest('[data-confirm-technical]');
  if(!button)return;
  const card=button.closest('[data-technical-card]');
  const note=card.querySelector('[data-technical-note]').value.trim();
  const resultReference=card.querySelector('[data-technical-reference]').value.trim();
  if(note.length<5)return toast('Bitte einen nachvollziehbaren Prüfvermerk eingeben.');
  if(!confirm(`Technisches Ergebnis „${card.querySelector('strong').textContent}“ verbindlich bestätigen?`))return;
  button.disabled=true;
  try{
    const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:document.querySelector('#programParticipantId').value,technicalConfirmation:{week:Number(button.dataset.week),stepId:button.dataset.stepId,note,resultReference}})});
    const data=await response.json();
    if(!response.ok)throw new Error(data.error);
    renderProgramControl(data);
    toast('Technisches Ergebnis wurde auditierbar bestätigt.');
    await loadParticipants();
  }catch(error){toast(error.message);button.disabled=false;}
});
async function openProgramControl(participantId){if(!participantId)return;programDialog.showModal();document.querySelector('#programParticipantName').textContent='Wird geladen …';try{const response=await fetch(`/api/program-control?participantId=${encodeURIComponent(participantId)}`);const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);}catch(error){programDialog.close();toast(error.message);}}
document.querySelector('#resetParticipantToOnboarding').addEventListener('click',async()=>{const id=document.querySelector('#programParticipantId').value;if(!id)return;if(!confirm('Möchtest du diesen Kunden wirklich auf den Onboarding-Start zurücksetzen?'))return;try{const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({participantId:id,resetToOnboarding:true})});const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);programDialog.close();toast('Kunde wurde auf Onboarding zurückgesetzt.');await loadParticipants();}catch(error){toast(error.message);}});
document.querySelector('#programForm').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#saveProgram');button.disabled=true;const gateUpdates=[...document.querySelectorAll('[data-correction-gate]')].filter(input=>String(input.checked)!==input.dataset.original).map(input=>({gateId:input.dataset.correctionGate,completed:input.checked}));const payload={participantId:document.querySelector('#programParticipantId').value,customerProfile:{name:document.querySelector('#customerProfileName').value,birthDate:document.querySelector('#customerBirthDate').value,street:document.querySelector('#customerStreet').value,postalCode:document.querySelector('#customerPostalCode').value,city:document.querySelector('#customerCity').value,country:document.querySelector('#customerCountry').value,phone:document.querySelector('#customerPhone').value,mobilePhone:document.querySelector('#customerMobilePhone').value,whatsappPhone:document.querySelector('#customerWhatsappPhone').value,whatsappSameAsMobile:document.querySelector('#customerWhatsappSame').checked,preferredCommunicationChannel:document.querySelector('#customerPreferredChannel').value,postalMailActive:document.querySelector('#customerPostalActive').checked},programStartDate:document.querySelector('#programStartDate').value,programStatus:document.querySelector('#programStatus').value,gateUpdates};try{const response=await fetch('/api/program-control',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error);renderProgramControl(data);programDialog.close();toast('Kundenstammdaten und Programmsteuerung wurden gespeichert.');await loadParticipants();if(activeCustomerDashboard?.person?.id===payload.participantId)await openCustomerDashboard(payload.participantId,customerDashboardPage);}catch(error){toast(error.message);}finally{button.disabled=false;}});

async function loadParticipants(){try{const response=await fetch('/api/participants');const data=await response.json();if(!response.ok)throw new Error(data.error);participants=data.participants.map(profile=>{const progress=profile.participant_progress?.[0]||{},parts=profile.name.split(' '),processWeek=Number(profile.process_week)||0,completedWeeks=Array.isArray(profile.completed_weeks)?profile.completed_weeks.map(Number):[];return{id:profile.id,isDemo:profile.is_demo===true||profile.permissions?.includes('demo_full_access')===true,linkedLeadId:profile.linked_lead_id,name:profile.name,email:profile.email,phone:profile.phone||'',mobilePhone:profile.mobile_phone||'',birthDate:profile.birth_date||'',street:profile.street||'',postalCode:profile.postal_code||'',city:profile.city||'',country:profile.country||'',whatsappPhone:profile.whatsapp_phone||'',whatsappSameAsMobile:profile.whatsapp_same_as_mobile===true,profilePhotoPath:profile.profile_photo_path||'',preferredChannel:profile.preferred_communication_channel||'email',postalActive:profile.postal_mail_active!==false,loginName:profile.portal_username||'',customerNumber:profile.customer_number||'',mustChangePassword:profile.must_change_password===true,passwordIssuedAt:profile.one_time_password_issued_at||null,inviteSentAt:profile.access_invite_sent_at||null,passwordChangedAt:profile.password_changed_at||null,week:processWeek,processWeek,releasedWeek:Number(profile.released_week)||0,completedWeeks,status:processWeek?`WEEK_${processWeek}`:'ONBOARDING',programStatus:progress.program_status||profile.status,accessMode:progress.access_mode||'time_based',startDate:progress.program_start_date||null,lastActivity:progress.last_activity_at||null,customerSince:profile.customer_since||profile.created_at||null,progress:Number.isFinite(Number(profile.completion_percent))?Number(profile.completion_percent):Math.round(completedWeeks.length/8*100),clarity:'—',next:'Kundenakte öffnen',initials:`${parts[0]?.[0]||''}${parts.at(-1)?.[0]||''}`,searchSource:profile};});document.querySelector('#activeCustomerCount').textContent=String(participants.filter(item=>customerStatus(item)==='active').length);}catch(error){toast(error.message);}const demoButton=document.querySelector('#openDemoCustomer');if(demoButton)demoButton.hidden=!participants.some(person=>person.isDemo);renderParticipants();renderParticipantLogins();renderGlobalContactSearch();}

const participantLoginDialog=document.querySelector('#participantLoginDialog'),participantLoginForm=document.querySelector('#participantLoginForm');
function showOneTimePassword(password=''){const result=document.querySelector('#oneTimePasswordResult'),value=document.querySelector('#oneTimePasswordValue'),toggle=document.querySelector('#toggleOneTimePassword');result.hidden=!password;value.dataset.password=password;value.textContent=password?'•'.repeat(Math.max(10,password.length)):'';if(toggle){toggle.setAttribute('aria-pressed','false');toggle.setAttribute('aria-label','Einmalpasswort anzeigen');toggle.textContent='◉';}}
function openParticipantLogin(id,oneTimePassword=''){const person=participants.find(item=>item.id===id);if(!person)return;participantLoginForm.elements.id.value=person.id;participantLoginForm.elements.customerNumber.value=person.customerNumber||'Wird automatisch vergeben';participantLoginForm.elements.loginName.value=person.loginName||'';document.querySelector('#participantLoginName').textContent=person.name;document.querySelector('#participantLoginEmail').textContent=person.email;const [label]=participantLoginStatus(person);document.querySelector('#participantPasswordState').textContent=`${label}${person.inviteSentAt?` · E-Mail zuletzt ${new Date(person.inviteSentAt).toLocaleString('de-DE')}`:''}`;showOneTimePassword(oneTimePassword);participantLoginDialog.showModal();}
document.querySelectorAll('[data-close-participant-login]').forEach(button=>button.addEventListener('click',()=>participantLoginDialog.close()));
participantLoginForm.addEventListener('submit',async event=>{event.preventDefault();const button=participantLoginForm.querySelector('[type="submit"]');button.disabled=true;try{const response=await fetch('/api/participants',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:participantLoginForm.elements.id.value,action:'update-login',loginName:participantLoginForm.elements.loginName.value})}),data=await response.json();if(!response.ok)throw new Error(data.error);await loadParticipants();participantLoginDialog.close();toast('Teilnehmer-Login wurde gespeichert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#issueOneTimePassword').addEventListener('click',async()=>{if(!confirm('Ein neues Einmalpasswort macht das bisherige Passwort sofort ungültig. Fortfahren?'))return;const button=document.querySelector('#issueOneTimePassword');button.disabled=true;try{const id=participantLoginForm.elements.id.value;const response=await fetch('/api/participants',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action:'issue-one-time-password'})}),data=await response.json();if(!response.ok)throw new Error(data.error);const person=participants.find(item=>item.id===id);if(person){person.mustChangePassword=true;person.passwordIssuedAt=data.issuedAt;}showOneTimePassword(data.oneTimePassword);document.querySelector('#participantPasswordState').textContent='Neues Einmalpasswort aktiv · Passwortwechsel beim nächsten Login erforderlich';renderParticipantLogins();toast('Einmalpasswort wurde erzeugt und wird nur jetzt angezeigt.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#sendParticipantLoginMail').addEventListener('click',async()=>{const button=document.querySelector('#sendParticipantLoginMail');button.disabled=true;try{const id=participantLoginForm.elements.id.value;const response=await fetch('/api/participants',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action:'send-login-mail'})}),data=await response.json();if(!response.ok)throw new Error(data.error);const person=participants.find(item=>item.id===id);if(person)person.inviteSentAt=data.sentAt;document.querySelector('#participantPasswordState').textContent=`Einmal-Link versendet · ${new Date(data.sentAt).toLocaleString('de-DE')}`;toast(data.message);}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#toggleOneTimePassword')?.addEventListener('click',event=>{const button=event.currentTarget,value=document.querySelector('#oneTimePasswordValue'),password=value.dataset.password||'',visible=button.getAttribute('aria-pressed')==='true';button.setAttribute('aria-pressed',String(!visible));button.setAttribute('aria-label',visible?'Einmalpasswort anzeigen':'Einmalpasswort wieder verbergen');button.textContent=visible?'◉':'⊘';value.textContent=visible?'•'.repeat(Math.max(10,password.length)):password;});
document.querySelector('#copyOneTimePassword').addEventListener('click',async()=>{const value=document.querySelector('#oneTimePasswordValue').dataset.password||'';if(!value)return;try{await navigator.clipboard.writeText(value);toast('Einmalpasswort wurde kopiert.');}catch{toast('Kopieren war nicht möglich. Bitte blende das Passwort ein und markiere es manuell.');}});
document.querySelector('#customerLoginPage')?.addEventListener('click',event=>{if(event.target.closest('[data-manage-customer-login]')&&activeCustomerDashboard?.person?.id)openParticipantLogin(activeCustomerDashboard.person.id);});
const tariffDialog=document.querySelector('#tariffDialog'),tariffForm=document.querySelector('#tariffForm');
function tariffPrice(value){return Number(value||0).toLocaleString('de-DE',{style:'currency',currency:'EUR'});}
function renderServiceTariffs(){const list=document.querySelector('#tariffList'),count=document.querySelector('#tariffCount'),active=serviceTariffs.filter(item=>item.is_active);if(count)count.textContent=`${active.length} aktiv · ${serviceTariffs.length} gesamt`;if(!list)return;list.innerHTML=serviceTariffs.length?serviceTariffs.map(tariff=>`<article class="tariff-card ${tariff.is_active?'active':'inactive'}"><header><div><span>${escapeHtml(tariff.code)}</span><h3>${escapeHtml(tariff.name)}</h3></div><div>${tariff.is_default?'<b>Standard</b>':''}<i>${tariff.is_active?'Aktiv':'Inaktiv'}</i></div></header><p>${escapeHtml(tariff.description||'Noch keine Tarifbeschreibung hinterlegt.')}</p><dl><div><dt>Produkt</dt><dd>${escapeHtml(tariff.product_label)}</dd></div><div><dt>Laufzeit</dt><dd>${escapeHtml(tariff.duration_label)}</dd></div><div><dt>Preis brutto</dt><dd>${tariffPrice(tariff.gross_price)}</dd></div><div><dt>Zahlungsmodell</dt><dd>${escapeHtml(tariff.payment_model)}</dd></div><div><dt>Zahlungsziel</dt><dd>${escapeHtml(tariff.payment_due)}</dd></div></dl><button type="button" class="secondary" data-edit-tariff="${escapeHtml(tariff.id)}">Tarif bearbeiten →</button></article>`).join(''):'<div class="tariff-empty"><strong>Noch kein Tarif angelegt</strong><span>Lege den ersten Tarif an, damit er im Vertragsabschluss ausgewählt werden kann.</span></div>';list.querySelectorAll('[data-edit-tariff]').forEach(button=>button.addEventListener('click',()=>openTariffDialog(button.dataset.editTariff)));}
async function loadServiceTariffs(){const response=await fetch('/api/leads?action=tariffs'),data=await response.json();if(!response.ok)throw new Error(data.error);serviceTariffs=data.tariffs||[];renderServiceTariffs();return serviceTariffs;}
function openTariffDialog(id=''){const tariff=serviceTariffs.find(item=>item.id===id);tariffForm.reset();tariffForm.elements.id.value=tariff?.id||'';tariffForm.elements.code.value=tariff?.code||'';tariffForm.elements.name.value=tariff?.name||'';tariffForm.elements.description.value=tariff?.description||'';tariffForm.elements.productLabel.value=tariff?.product_label||'';tariffForm.elements.durationLabel.value=tariff?.duration_label||'8 Wochen';tariffForm.elements.grossPrice.value=tariff?.gross_price||'';tariffForm.elements.paymentModel.value=tariff?.payment_model||'Einmalzahlung';tariffForm.elements.paymentDue.value=tariff?.payment_due||'7 Tage nach Abschluss';tariffForm.elements.additionalAgreements.value=tariff?.additional_agreements||'';tariffForm.elements.sortOrder.value=tariff?.sort_order??serviceTariffs.length*10;tariffForm.elements.isActive.checked=tariff?.is_active!==false;tariffForm.elements.isDefault.checked=Boolean(tariff?.is_default||!serviceTariffs.length);document.querySelector('#tariffDialogTitle').textContent=tariff?'Tarif bearbeiten':'Tarif anlegen';tariffDialog.showModal();requestAnimationFrame(()=>tariffForm.elements.name.focus());}
document.querySelector('#openTariff')?.addEventListener('click',()=>openTariffDialog());
document.querySelectorAll('[data-close-tariff]').forEach(button=>button.addEventListener('click',()=>tariffDialog.close()));
