  bookingSettingsForm.elements.defaultDurationMinutes.value=String(settings.defaultDurationMinutes);
  bookingSettingsForm.querySelectorAll('[name="offeredDuration"]').forEach(input=>{input.checked=settings.offeredDurations.includes(Number(input.value));});
