function renderLeadTasks(){if(!activeLeadDashboard)return;const tasks=activeLeadDashboard.tasks||[],questions=activeLeadDashboard.questions||[];const items=leadTaskFilter==='questions'?questions:[...questions,...tasks];document.querySelector('#leadTaskList').innerHTML=items.length?items.map(item=>{const question=Boolean(item.question);if(question)return`<article class="question ${item.status==='answered'?'done':''}"><div><strong>Woche ${item.week} · Kundenfrage</strong><span>${item.status==='answered'?'Beantwortet':'Offen'}</span></div><p>${escapeHtml(item.question)}</p><small>${crmDate(item.created_at)}</small>${item.status==='open'?`<button class="lead-card-action" type="button" data-answer-question="${escapeHtml(item.id)}">Als beantwortet markieren</button>`:''}</article>`;return`<article class="${item.completed?'done':''}"><label><input type="checkbox" data-lead-task-id="${escapeHtml(item.id)}" ${item.completed?'checked':''}><span><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.details||'Interne Aufgabe')}</p><small>${item.due_at?`Fällig ${crmDate(item.due_at)}`:'Ohne Fälligkeit'}</small></span></label></article>`;}).join(''):'<div class="lead-empty">Noch keine Aufgaben oder Kundenfragen vorhanden.</div>';document.querySelectorAll('[data-lead-task-id]').forEach(input=>input.addEventListener('change',async()=>{try{await saveLeadDashboardRecord({recordType:'toggle_task',taskId:input.dataset.leadTaskId,completed:input.checked});}catch(error){input.checked=!input.checked;toast(error.message);}}));document.querySelectorAll('[data-answer-question]').forEach(button=>button.addEventListener('click',async()=>{try{await saveLeadDashboardRecord({recordType:'answer_question',questionId:button.dataset.answerQuestion});}catch(error){toast(error.message);}}));}
function renderSalesCallCard(lead){const answers=lead.qualification_answers||{},answered=Array.from({length:6},(_,index)=>answers[`q${index+1}`]).filter(value=>String(value||'').trim()).length;const completed=lead.status==='consultation'||['offer','customer'].includes(lead.status);document.querySelector('#leadSalesCallStatus').textContent=completed?'Gespräch geführt':lead.appointment_start?'Termin geplant':'Noch nicht geplant';document.querySelector('#leadSalesCallOverview').innerHTML=`<div><span>${lead.appointment_start?'✓':'○'}</span><p><b>Termin</b><small>${lead.appointment_start?crmDate(lead.appointment_start):'Noch nicht geplant'}</small></p></div><div><span>${answered===6?'✓':answered}</span><p><b>Gesprächsleitfaden</b><small>${answered} von 6 Antworten dokumentiert</small></p></div><div><span>${completed?'✓':'○'}</span><p><b>Abschlussentscheidung</b><small>${completed?'Gespräch abgeschlossen':'Noch offen'}</small></p></div>`;}
function renderLeadDashboard(data){activeLeadDashboard=data;const lead=data.lead,initials=lead.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();document.querySelector('#leadDashboardInitials').textContent=initials;document.querySelector('#leadDashboardName').textContent=lead.name;document.querySelector('#leadDashboardStatus').textContent=leadStatusLabels[lead.status]||lead.status;document.querySelector('#markLeadLost').classList.toggle('active',lead.status==='lost');document.querySelector('#markLeadLater').classList.toggle('active',lead.status==='later');document.querySelector('#leadDashboardContact').textContent=`${lead.email} · ${lead.phone||'keine Telefonnummer'}`;document.querySelector('#leadDashboardConvert').textContent=lead.converted_user_profile_id?'Teilnehmerkonto verwalten →':'Vertragsabschluss erfassen →';const signed=(data.contracts||[]).some(item=>item.status==='signed'&&item.document_confirmed_at&&item.video_contract_confirmed_at);const stageByStatus={new:0,contacted:1,scheduled:2,consultation:3,offer:4,later:0,customer:6,lost:0};let current=stageByStatus[lead.status]??0;if(signed&&current<5)current=5;const stages=[['Anfrage','Eingegangen'],['Kontakt','Qualifizieren'],['Termin','Erstgespräch'],['Gespräch','Bedarf klar'],['Angebot','Entscheidung'],['Vertrag','Dokument + Video'],['Teilnehmer','8 Wochen']];document.querySelector('#leadSalesProgressCount').textContent=`Schritt ${current+1} von 7`;document.querySelector('#leadProgressTrack').innerHTML=stages.map(([title,copy],index)=>`<div class="lead-progress-step ${index<current?'done':index===current?'current':''}"><span>${index<current?'✓':index+1}</span><b>${title}</b><small>${copy}</small></div>`).join('');document.querySelector('#leadContactDetails').innerHTML=`<dl class="lead-detail-list"><div><dt>E-Mail</dt><dd>${escapeHtml(lead.email)}</dd></div><div><dt>Telefon</dt><dd>${escapeHtml(lead.phone||'Nicht hinterlegt')}</dd></div><div><dt>Quelle</dt><dd>${escapeHtml(lead.utm_source||lead.source||'Unbekannt')}</dd></div><div><dt>Anfrage</dt><dd>${escapeHtml(lead.challenge||'Nicht beschrieben')}</dd></div><div><dt>Eingang</dt><dd>${crmDate(lead.created_at)}</dd></div></dl>`;document.querySelector('#leadOpenBalance').textContent=euro(data.finance.openBalance);document.querySelector('#leadBalanceState').textContent=data.finance.openBalance>0?'Zahlung oder Restbetrag noch offen':'Keine offenen Forderungen';document.querySelector('#leadBalanceDetails').innerHTML=`<div><dt>Unterzeichnete Verträge</dt><dd>${euro(data.finance.contractTotal)}</dd></div><div><dt>Gebuchte Zahlungen</dt><dd>${euro(data.finance.paidTotal)}</dd></div>`;document.querySelector('#leadCommunicationList').innerHTML=data.communications.length?data.communications.map(item=>`<article><div><strong>${escapeHtml(item.subject)}</strong><span>${communicationLabels[item.direction]||item.direction}</span></div><p>${escapeHtml(item.preview||'Kein Vorschautext')}</p><small>${crmDate(item.occurred_at)}</small></article>`).join(''):'<div class="lead-empty">Noch kein E-Mail-Verkehr protokolliert. Termin- und Zugangsmails erscheinen hier automatisch.</div>';document.querySelector('#leadContractList').innerHTML=data.contracts.length?data.contracts.map(item=>`<article class="${item.status}"><div><strong>${escapeHtml(item.title)}</strong><span>${contractStatusLabels[item.status]||item.status}</span></div><p>${euro(item.amount)}${item.contract_number?` · ${escapeHtml(item.contract_number)}`:''}</p><div class="lead-contract-checks"><i class="${item.document_confirmed_at?'ok':''}">${item.document_confirmed_at?'✓':'○'} Vertragsdokument</i><i class="${item.video_contract_confirmed_at?'ok':''}">${item.video_contract_confirmed_at?'✓':'○'} Videovertrag</i></div><nav>${item.document_storage_path?`<a href="/api/leads?action=contract-download&id=${encodeURIComponent(lead.id)}&contractId=${encodeURIComponent(item.id)}" target="_blank" rel="noopener">PDF öffnen</a>`:''}${item.video_recording_path?`<a href="/api/leads?action=video-recording-download&id=${encodeURIComponent(lead.id)}&contractId=${encodeURIComponent(item.id)}" target="_blank" rel="noopener">Video ansehen</a>`:''}</nav><small>${item.signed_at?`Video-Abschluss ${crmDate(item.signed_at)}`:`Angelegt ${crmDate(item.created_at)}`}</small></article>`).join(''):'<div class="lead-empty">Noch kein Vertrag angelegt.</div>';document.querySelector('#leadNotesText').textContent=lead.internal_notes||'Noch keine internen Notizen vorhanden.';const bank=data.bankAccount;document.querySelector('#leadBankDetails').innerHTML=bank?`<div><dt>Kontoinhaber</dt><dd>${escapeHtml(bank.account_holder||'—')}</dd></div><div><dt>IBAN</dt><dd>${escapeHtml(bank.iban||'—')}</dd></div><div><dt>BIC</dt><dd>${escapeHtml(bank.bic||'—')}</dd></div><div><dt>Verwendungszweck</dt><dd>${escapeHtml(bank.payment_reference||'—')}</dd></div>`:'<div><dt>Status</dt><dd>Noch nicht hinterlegt</dd></div>';const next=[];if(!lead.appointment_start)next.push('Erstgespräch mit dem Interessenten planen');if(!data.contracts.length)next.push('Passenden Vertrag anlegen und versenden');else if(!signed&&!lead.converted_user_profile_id)next.push('Vertragsdokument und Videovertrag vollständig bestätigen');if(data.finance.openBalance>0)next.push(`${euro(data.finance.openBalance)} Zahlungseingang abgleichen`);if(!bank)next.push('Bankverbindung und Verwendungszweck hinterlegen');if(data.questions.some(item=>item.status==='open'))next.push(`${data.questions.filter(item=>item.status==='open').length} Kundenfrage(n) beantworten`);if(!next.length)next.push('Akte ist vollständig – nächsten persönlichen Kontakt planen');document.querySelector('#leadNextSteps').innerHTML=next.slice(0,4).map((item,index)=>`<div><span>${index+1}</span><p>${escapeHtml(item)}</p></div>`).join('');renderLeadTasks();renderSalesCallCard(lead);renderSalesContractState();}
async function loadLeadDashboard(id=activeLeadDashboard?.lead?.id){if(!id)return;const response=await fetch(`/api/leads?action=dashboard&id=${encodeURIComponent(id)}`),data=await response.json();if(!response.ok)throw new Error(data.error);renderLeadDashboard(data);}
function setLeadDashboardPage(page,syncNavigation=true){const allowed=['overview','conversation','messages','contracts','finance','bank','tasks','notes'];leadDashboardPage=allowed.includes(page)?page:'overview';document.querySelectorAll('[data-lead-page]').forEach(section=>{const active=section.dataset.leadPage===leadDashboardPage;section.hidden=!active;section.classList.toggle('active',active);});if(syncNavigation&&activeLeadDashboard)renderContextNavigation('leads');window.scrollTo({top:0,behavior:'auto'});}
async function openLeadDashboard(id,page='overview'){leadDashboardPage=page;document.querySelector('#leadListView').classList.add('hidden');document.querySelector('#leadDashboard').classList.remove('hidden');document.querySelector('#leadDashboardName').textContent='Akte wird geladen …';try{await loadLeadDashboard(id);setLeadDashboardPage(page,false);renderContextNavigation('leads');}catch(error){document.querySelector('#leadListView').classList.remove('hidden');document.querySelector('#leadDashboard').classList.add('hidden');toast(error.message);}}
function resetLeadListView(){activeLeadDashboard=null;leadDashboardPage='overview';document.querySelector('#leadDashboard').classList.add('hidden');document.querySelector('#leadListView').classList.remove('hidden');setLeadDashboardPage('overview',false);}
function closeLeadDashboard(){resetLeadListView();renderLeadRows();renderContextNavigation('leads');}
const leadRecordDialog=document.querySelector('#leadRecordDialog'),leadRecordForm=document.querySelector('#leadRecordForm');
const recordDefinitions={contract:{title:'Vertragsabschluss erfassen',copy:'Tarif, Preis und Laufzeit stammen zentral aus den Einstellungen. Nur ein unterschriebener Vertrag mit Vertragsdokument und Videovertrag erzeugt automatisch einen Teilnehmer.',fields:`<label class="wide">Tarif<select name="tariffId" required></select></label><label class="wide">Vertragsbezeichnung<input name="title" required readonly></label><div class="lead-generated-contract-number"><span>Vertragsnummer</span><strong>Wird automatisch vergeben</strong><small>Schema: FDD–Jahr–laufende Nummer</small></div><label>Betrag in Euro<input name="amount" type="number" min="0" step="0.01" required readonly></label><label>Status<select name="status"><option value="draft">Entwurf</option><option value="sent">Versendet</option><option value="signed">Unterschrieben</option><option value="cancelled">Storniert</option></select></label><label>Programmstart<input name="programStartDate" type="date" required></label><fieldset class="wide lead-contract-confirmations"><legend>Verbindliche Abschlussnachweise</legend><label><input name="documentConfirmed" type="checkbox" value="true"> Vertragsdokument vollständig unterzeichnet</label><label><input name="videoContractConfirmed" type="checkbox" value="true"> Videovertrag vollständig durchgeführt</label></fieldset>`},payment:{title:'Zahlungseingang erfassen',copy:'Der gebuchte Betrag wird mit dem Vertragsvolumen abgeglichen.',fields:`<label>Betrag in Euro<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Buchungsdatum<input name="bookedAt" type="date" required></label><label class="wide">Verwendungszweck / Referenz<input name="reference" placeholder="z. B. FDD-2026-0001"></label>`},communication:{title:'E-Mail protokollieren',copy:'Manueller Eintrag für den nachvollziehbaren Kommunikationsverlauf.',fields:`<label>Richtung<select name="direction"><option value="outbound">Ausgang</option><option value="inbound">Eingang</option><option value="system">System</option></select></label><label class="wide">Betreff<input name="subject" required></label><label class="wide">Vorschau<textarea name="preview"></textarea></label>`},task:{title:'Aufgabe anlegen',copy:'Interne Aufgaben stehen gemeinsam mit den Fragen aus dem Kundenprozess.',fields:`<label class="wide">Aufgabe<input name="title" required></label><label>Fällig am<input name="dueAt" type="date"></label><label class="wide">Details<textarea name="details"></textarea></label>`},bank:{title:'Bankverbindung bearbeiten',copy:'Die Daten dienen dem manuellen Abgleich eingehender Überweisungen.',fields:`<label class="wide">Kontoinhaber<input name="accountHolder"></label><label class="wide">IBAN<input name="iban"></label><label>BIC<input name="bic"></label><label class="wide">Verwendungszweck<input name="paymentReference"></label>`},note:{title:'Interne Notizen bearbeiten',copy:'Diese Notizen sind ausschließlich für Administratoren sichtbar.',fields:`<label class="wide">Notizen<textarea name="notes"></textarea></label>`}};
function applyTariffToLeadContract(id){const tariff=serviceTariffs.find(item=>item.id===id);if(!tariff)return;leadRecordForm.elements.title.value=tariff.product_label;leadRecordForm.elements.amount.value=Number(tariff.gross_price).toFixed(2);}
async function openLeadRecord(type){const definition=recordDefinitions[type];if(!definition||!activeLeadDashboard)return;leadRecordForm.reset();leadRecordForm.elements.recordType.value=type;document.querySelector('#leadRecordTitle').textContent=definition.title;document.querySelector('#leadRecordCopy').textContent=definition.copy;document.querySelector('#leadRecordFields').innerHTML=definition.fields;if(type==='payment')leadRecordForm.elements.bookedAt.value=browserDateKey();if(type==='contract'){try{await loadServiceTariffs();}catch(error){return toast(error.message);}const active=serviceTariffs.filter(item=>item.is_active),selected=active.find(item=>item.is_default)||active[0];if(!selected)return toast('Bitte lege zuerst unter Einstellungen → Tarife einen aktiven Tarif an.');leadRecordForm.elements.tariffId.innerHTML=active.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)} · ${tariffPrice(item.gross_price)}</option>`).join('');leadRecordForm.elements.tariffId.value=selected.id;leadRecordForm.elements.tariffId.addEventListener('change',event=>applyTariffToLeadContract(event.target.value));applyTariffToLeadContract(selected.id);leadRecordForm.elements.programStartDate.value=browserDateKey();}if(type==='note')leadRecordForm.elements.notes.value=activeLeadDashboard.lead.internal_notes||'';if(type==='bank'&&activeLeadDashboard.bankAccount){const bank=activeLeadDashboard.bankAccount;leadRecordForm.elements.accountHolder.value=bank.account_holder||'';leadRecordForm.elements.iban.value=bank.iban||'';leadRecordForm.elements.bic.value=bank.bic||'';leadRecordForm.elements.paymentReference.value=bank.payment_reference||'';}leadRecordDialog.showModal();}
async function saveLeadDashboardRecord(payload){const id=activeLeadDashboard?.lead?.id;if(!id)throw new Error('Keine Interessentenakte geöffnet.');const response=await fetch('/api/leads?action=dashboard-record',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,...payload})}),data=await response.json();if(!response.ok)throw new Error(data.error);await loadLeadDashboard(id);return data;}
const leadFollowUpDialog=document.querySelector('#leadFollowUpDialog'),leadFollowUpForm=document.querySelector('#leadFollowUpForm');
function openLeadFollowUp(){const existing=(activeLeadDashboard?.tasks||[]).find(item=>!item.completed&&item.task_type==='lead_follow_up'),suggested=new Date();suggested.setDate(suggested.getDate()+30);leadFollowUpForm.reset();leadFollowUpForm.elements.followUpDate.min=browserDateKey();leadFollowUpForm.elements.followUpDate.value=existing?.due_at||browserDateKey(suggested);leadFollowUpDialog.showModal();requestAnimationFrame(()=>leadFollowUpForm.elements.followUpDate.focus());}
async function setLeadInterestStatus(status,followUpDate=null){const leadId=activeLeadDashboard?.lead?.id;if(!leadId)throw new Error('Keine Interessentenakte geöffnet.');const response=await fetch('/api/leads?action=set-interest-status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:leadId,status,followUpDate})}),data=await response.json();if(!response.ok)throw new Error(data.error);if(leadFollowUpDialog.open)leadFollowUpDialog.close();updateLeadCache(data.lead);await Promise.all([loadLeads(),loadCommandDashboard()]);setLeadListFilter(status);toast(data.message);return data;}
document.querySelector('#closeLeadDashboard').addEventListener('click',closeLeadDashboard);document.querySelector('#editLeadProfile').addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id));document.querySelector('#openLeadSalesCall').addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id));document.querySelector('#leadDashboardConvert').addEventListener('click',()=>activeLeadDashboard?.lead?.converted_user_profile_id?openLeadEditor(activeLeadDashboard.lead.id):openLeadRecord('contract'));document.querySelectorAll('[data-lead-edit="profile"]').forEach(button=>button.addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id)));document.querySelectorAll('[data-lead-record]').forEach(button=>button.addEventListener('click',()=>openLeadRecord(button.dataset.leadRecord)));document.querySelectorAll('[data-close-lead-record]').forEach(button=>button.addEventListener('click',()=>leadRecordDialog.close()));document.querySelectorAll('[data-lead-task-filter]').forEach(button=>button.addEventListener('click',()=>{leadTaskFilter=button.dataset.leadTaskFilter;document.querySelectorAll('[data-lead-task-filter]').forEach(item=>item.classList.toggle('active',item===button));renderLeadTasks();}));leadRecordForm.addEventListener('submit',async event=>{event.preventDefault();const button=leadRecordForm.querySelector('[type="submit"]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(leadRecordForm));const result=await saveLeadDashboardRecord(payload);leadRecordDialog.close();if(payload.recordType==='communication')await loadCommunications();if(result.participantActivated){await Promise.all([loadParticipants(),loadLeads(),loadUsers(),loadCommunications()]);openParticipantLogin(result.participant.profileId,result.participant.oneTimePassword||'');toast('Vertrag abgeschlossen: Teilnehmer-Login und Einmalzugang wurden automatisch erstellt.');}else toast('Akte wurde aktualisiert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#markLeadLost').addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{await setLeadInterestStatus('lost');}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#markLeadLater').addEventListener('click',openLeadFollowUp);
document.querySelectorAll('[data-close-lead-follow-up]').forEach(button=>button.addEventListener('click',()=>leadFollowUpDialog.close()));
leadFollowUpForm.addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{await setLeadInterestStatus('later',leadFollowUpForm.elements.followUpDate.value);}catch(error){toast(error.message);}finally{button.disabled=false;}});
async function saveLead(showMessage=true,refreshForm=true,payload=leadPayload()){const response=await fetch('/api/leads?action=update',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);if(activeLeadDashboard?.lead?.id===data.lead.id)activeLeadDashboard.lead=data.lead;if(refreshForm)renderLeadDialog(data.lead);if(showMessage)toast('Interessent wurde gespeichert.');return data.lead;}
function persistLeadDraft(){clearTimeout(leadAutosaveTimer);const payload=leadPayload(),revision=leadRevision;if(!payload.id||!payload.firstName.trim()||!payload.lastName.trim()||!/^\S+@\S+\.\S+$/.test(payload.email)||!payload.mobilePhone.trim()){setAutosaveState('#leadAutosaveStatus','error','Pflichtfelder für Kontakt vollständig ergänzen');return Promise.resolve(false);}if(!payload.whatsappSameAsMobile&&!payload.whatsappPhone.trim()){setAutosaveState('#leadAutosaveStatus','error','Abweichende WhatsApp-Nummer ergänzen');return Promise.resolve(false);}leadAutosaveQueue=leadAutosaveQueue.catch(()=>{}).then(async()=>{setAutosaveState('#leadAutosaveStatus','saving','Wird automatisch gespeichert …');await saveLead(false,false,payload);leadPersistedRevision=Math.max(leadPersistedRevision,revision);if(leadPersistedRevision===leadRevision)setAutosaveState('#leadAutosaveStatus','saved','Alle Änderungen gespeichert');return true;}).catch(error=>{setAutosaveState('#leadAutosaveStatus','error',error.message||'Speichern fehlgeschlagen');throw error;});return leadAutosaveQueue;}
const leadDraftFields=new Set(['firstName','lastName','email','mobilePhone','phone','hasAlternateWhatsapp','whatsappPhone','status','q1','q2','q3','q4','q5','q6']);
leadForm.addEventListener('input',event=>{if(!leadDraftFields.has(event.target.name))return;leadRevision+=1;setAutosaveState('#leadAutosaveStatus','saving','Wird automatisch gespeichert …');clearTimeout(leadAutosaveTimer);leadAutosaveTimer=setTimeout(()=>persistLeadDraft().catch(()=>{}),650);});
leadForm.addEventListener('change',event=>{if(!leadDraftFields.has(event.target.name))return;leadRevision+=1;setAutosaveState('#leadAutosaveStatus','saving','Wird automatisch gespeichert …');clearTimeout(leadAutosaveTimer);leadAutosaveTimer=setTimeout(()=>persistLeadDraft().catch(()=>{}),250);});
leadForm.addEventListener('submit',async event=>{event.preventDefault();if(leadWizardStep<leadWizardPages.length){if(validateLeadWizardStep())setLeadWizardStep(leadWizardStep+1);return;}leadStepSave.disabled=true;clearTimeout(leadAutosaveTimer);try{await leadAutosaveQueue.catch(()=>{});const saved=await saveLead(false);const response=await fetch('/api/leads?action=complete-sales-conversation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:saved.id})}),data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);leadDialog.close();toast(data.message);await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}finally{leadStepSave.disabled=false;}});
document.querySelector('#refreshSlots').addEventListener('click',loadAvailableSlots);
document.querySelector('#slotRangeStart').addEventListener('change',loadAvailableSlots);
leadForm.elements.appointmentDuration.addEventListener('change',()=>{leadForm.elements.appointmentStart.value='';showSelectedSlot('');loadAvailableSlots();});
document.querySelector('#scheduleLead').addEventListener('click',async()=>{const button=document.querySelector('#scheduleLead'),start=leadForm.elements.appointmentStart.value,duration=Number(leadForm.elements.appointmentDuration.value);if(!start)return toast('Bitte einen angezeigten freien Termin auswählen.');button.disabled=true;try{const saved=await saveLead(false);const response=await fetch('/api/leads?action=schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:saved.id,start:new Date(start).toISOString(),duration})});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);toast(data.calendarConnected?'Termin und Meet wurden vorbereitet. Die Einladung folgt beim Abschluss.':'Termin gespeichert. Google Meet wird nach Verbindung der Schnittstelle ergänzt.');await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#cancelLeadAppointment').addEventListener('click',async()=>{if(!confirm('Termin wirklich absagen? Google informiert den eingeladenen Interessenten.'))return;try{const response=await fetch('/api/leads?action=cancel-appointment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:leadForm.elements.id.value})});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);toast('Termin wurde abgesagt.');await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}});

